            "brett.erkl.was" to "Isch dis Handy während de Session fescht ufem Brätt, misst sin Chreisel, wie s Brätt nickt und rollt – diräkt a de Quelle statt am Handglänk.",
            "brett.erkl.wie" to "So gaht's: Handy wasserdicht ipackt flach ufem Deck befestige und d Ufnahm i de Pumpfoil-App ufem Handy starte. D Uhr cha gliichzitig mitlaufe. Dass s Handy am Brätt gsi isch, merkt d Uswärtig meischtens sälber.",
            "brett.erkl.bringt" to "Was es bringt: Du gsehsch, wie ruhig dis Brätt bim Pumpe liit, wie fescht es pro Pump nickt und rollt und öb sich das zwüsche Foils, Kurve und Grade unterscheidet. Jedi söttigi Ufnahm hilft usserdem, d Pump-Erkännig für d Uhr z verbessere.",
            "brett.erkl.daten" to "Was für Date du überchunsch: Nicke und Rolle pro Pump, Schräglag, Takt, Kurve gäge Grad und de Hub (d Uf- und Abbewegig, sobald de Pumptakt sicher erkännt isch) – pro Lauf und do als Übersicht über alli Läuf und pro Foil.",
