            "sessions.uploadReplaceAsk" to "Die Fahrt isch scho da (Session #{id}), aber d Datei isch e anderi. Alti Session lösche und dur die Datei ersetze?\n\nNur zueschnide gaht au ohni neui Datei: i de Session unter „{trim}“.",
            "team.regeln.haftung.titel" to "Haftig",
            "team.regeln.haftung.text" to "Events veranstalted d Teams sälber. pumpfoil.org het kei Iifluss uf Events und uf Zuesage, wo drin gmacht wärded, ob finanziell oder andersch, und übernimmt dafür kei Verantwortig. De Rächtswäg isch usgschlosse. Zahlige und alli andere Abmachige regled Veranstalter und Teilnähmer unabhängig vo pumpfoil.org.\nGnau so übernimmt pumpfoil.org kei Verantwortig defür, dass gmässni Wärt und Date stimmed oder nöd manipuliert worde sind. Azeigt wird, was de öffentlich Quellcode uf GitHub us de ufeglade Date usrächnet; wiiteri Zuesage gits kei.",
            "notif.typeComment" to "Kommentär zu mine Sessions",
