            "guide.appleSub" to "watchOS 9+",
            "guide.a.s1Title" to "1. App installiere:",
            "guide.a.s1" to "usem App Store.",
            "guide.a.s2Title" to "2. Verbinde — optional:",
            "guide.a.s2a" to "Du chasch sofort ohni Konto ufnäh („Spöter verbinde“) und d Session spöter ufelade. Zum Zuordne: i de Watch-App „Verbinde“ → „Pairing-Code mache“ — de aazeigti Code da im Tab",
            "guide.a.s2b" to "ygäh.",
            "guide.a.s3Title" to "3. Datefälder:",
            "guide.a.s3" to "direkt uf de Uhr wüschbari Syte (yystellbar im Tab „Datefälder“). Stopp-Chnopf am Aafang und Ändi vo de Syte.",
            "guide.a.s4Title" to "4. Ufnäh:",
            "guide.a.s4" to "App ufmache → Start → foile → Stop. Ufnahm lauft au offline; Sync passiert automatisch, sobald online.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. App uf de Uhr installiere:",
            "guide.w.s1" to "de Play Store uf de Uhr ufmache und nach „Pumpfoil“ sueche.",
            "guide.w.s1Note" to "De Play Store uf em Händy installiert d Händy-App — d Uhre-App isch e eigeni Installation, direkt uf de Uhr.",
            "guide.w.s2Title" to "2. Verbinde — optional:",
            "guide.w.s2a" to "wie bi de Apple Watch — ohni Konto ufnäh isch möglich, spöter verbinde; oder i de Uhr-App „Verbinde“ → „Pairing-Code mache“ und de Code da im Tab",
            "guide.w.s2b" to "ygäh.",
            "guide.w.s3Title" to "3. Datefälder:",
            "guide.w.s3" to "wüschbari Syte, yystellbar im Tab „Datefälder“.",
            "guide.w.s4Title" to "4. Ufnäh:",
            "guide.w.s4" to "App ufmache → Start → foile → Stop. Offline-Ufnahm + automatische Sync.",
            "guide.amazfitSub" to "Unser Recorder läuft auf Amazfit-Uhren mit Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 u. a.).",
            "guide.z.store" to "Hol die Zepp-App und finde Pumpfoil in deren integriertem App Store:",
            "guide.z.s1" to "Installiere die Zepp-App (oben) und verbinde deine Amazfit dort wie gewohnt.",
            "guide.z.s2" to "In der Zepp-App: Profil → deine Amazfit → App Store → „Pumpfoil“ suchen → Installieren.",
            "guide.z.s3" to "Öffne Pumpfoil auf der Uhr, wische zu ›Verbinden‹ für einen Code und gib ihn ein unter ",
            "guide.z.s4" to "Drücke START zum Aufzeichnen. GPS und Puls werden automatisch über WLAN/Telefon hochgeladen.",
            "guide.huaweiSub" to "Üse Recorder lauft uf de HUAWEI WATCH 5 (HarmonyOS 5/6). Nach em Kopple ladet d Uhr sälber ufe – ohni Handy-App.",
            "guide.h.s1" to "Mach uf de Uhr d AppGallery uf, such „Pumpfoil“ und installier d App. Erlaub Standort und Körpersensore.",
            "guide.h.s2" to "Mach Pumpfoil uf, wüsch ufe zu de Iistellige und tipp uf ›pumpfoil.org‹ – d Uhr zeigt en Code. Gib en ii under ",
            "guide.h.s3" to "Tipp uf START. STOPP und Pause 2 Sekunde hebe, Verwerfe zwöimal tippe.",
            "guide.h.s4" to "Nach em Stopp ladet d Uhr sälber ufe, sobald si Internet het (WLAN oder übers kopplete Handy). Denn staht „All sent“ uf em Startbildschirm.",
            "guide.preview" to "So gsehts uf de Uhr us:",
            "guide.previewVer" to "So gsehts uf de Uhr us (v1.0.24):",
            "guide.cap.gStart" to "Start: GPS parat → START",
            "guide.cap.gSettings" to "MENU halte → Yystellige",
