            "guide.settings.title" to "Iistellige für dini Uhr",
            "guide.settings.intro" to "Sobald d’Uhr verbunde isch, findsch under ",
            "guide.settings.intro2" to " zu jedere Uhr zwei Regler. Si wirked uf d’Uhr sälber — si übernimmt si bim nächschte Start vo de App, ohni Update. Wenn dir d’Batterieziit wichtig isch, sind das d’Stellschruube.",
            "guide.settings.recordTitle" to "Ufnahm-Modus (alli Uhre):",
            "guide.settings.record" to "25 Hz, 10 Hz oder nur GPS. 10 Hz spart Batterie und choschtet fascht nüt — mir hend beidi Rate über die glichi Sessions grächnet: de Pump-Zähler wiicht weniger als es halbs Prozänt ab, und weli Abschnitt als Foile zelled, isch zu 99,9 % identisch.",
            "guide.settings.gnssTitle" to "Satellitesystem (nur Garmin):",
            "guide.settings.gnss" to "Voriistellt isch di bescht Stufe, wo dini Uhr cha — alli System über zwei Frequenzbänder. Die findet d’Position am schnellschte und hebt si am beschte, choschtet aber düütlich Batterie. „Ohni zwöits Frequenzband“ behebt alli System und lat nur s’tüüre Extraband wäg: de gröschti Spareffekt bi chliinschtem Verlust.",
            "guide.settings.gpsWarn" to "Nur GPS spart am meischte, wirft aber Pump-Zähler, Kadänz und Gleitphase komplett wäg — also grad die Zahle, für wo die App da isch. Wähl’s nur, wenn dini Uhr susch nöd durehebt.",
            "guide.settings.zepp" to "Bi Amazfit wirkt de Ufnahm-Modus na nöd — d’Uhr nimmt mit ihrer eigene Rate uf. Sprach, Pausenaasicht und eigni Layouts holt si sich dergäge vo da.",
            "watches.title" to "Unterstützti Uhre",
            "watches.intro" to "Weli Uhr liiferet weli Date — du entscheidsch. Langfristig wänd mer alli gängige Sportuhre aabinde.",
            "watches.colDevice" to "Uhr",
            "watches.colGps" to "GPS · Distanz · Speed",
            "watches.colHr" to "Puls",
            "watches.colPump" to "Pumps & Gleitphase",
            "watches.colStatus" to "Status",
            "watches.foot" to "Pumps & Gleitphase bruuched Roh-Beschlünigung (≥25 Hz) direkt vo de Uhr. GPS-Stats chamer bi vielne Marke au per FIT-/Datenimport uswerte.",
            "watches.legYes" to "voll unterstützt",
            "watches.legPartial" to "iigschränkt",
            "watches.legNo" to "nöd verfüegbar",
            "watches.linkAccount" to "Konto-Verchnüpfig verfüegbar",
            "watches.linkViaSuunto" to "über Mi Fitness → Suunto",
            "watches.nGarmin" to "Älteri Modäll ohni Roh-Accel: GPS-Stats wärded trotzdem uswertet.",
            "watches.nApple" to "Roh-Beschlünigung über Core Motion.",
            "watches.nWear" to "Lauft uf jeder Wear-OS-3+-Uhr — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Sensor-Zuegriff je nach Modäll.",
            "watches.nHuaweiW5" to "Ladet nach em Kopple per Code sälber ufe, ohni Handy-App. Neu i de AppGallery.",
            "watches.nHuawei" to "Am Schaffe: Ufnahm uf de Uhr, Übertragig über d Pumpfoil-App uf emne Android-Handy. Weli Date d Uhre liefered, mues no tescht werde.",
            "watches.nPolar" to "Konto verchnüpfe → Trainings importiere (GPS + HR). De hochfrequänt Accel-Stream für d Pump-Erkennig git de API-Export nöd (nur via separate BLE-Sensor).",
            "watches.nSuunto" to "Konto verchnüpfe → Trainings importiere (GPS + HR). De hochfrequänt Accel-Stream für d Pump-Erkennig git de FIT-Export (nonig) nöd.",
            "watches.nXiaomi" to "Kei App uf de Uhr möglich (Xiaomi lot kei frömdi Apps zue). Defür schickt Mi Fitness dini Trainings offiziell i d Suunto-App — verchnüpf Suunto und si lande bi eus. Aaleitig under „Konten verknüpfen“.",
            "watches.nFitbit" to "Drittaabieter-Apps sind iigstellt worde.",
            "watches.nStrava" to "Import wär technisch machbar, lieferet per API aber kein hochfrequente Roh-Accel (also kei Pump-Erkennig) und staht hinder Paywall + API-Uflage, wo nöd zum offene Projekt passed — drum bewusst nöd integriert.",
            "watches.subStrava" to "Aktivitäte-Portal",
