            "guide.appleSub" to "watchOS 9+",
            "guide.a.s1Title" to "1. App installieren:",
            "guide.a.s1" to "aus dem App Store.",
            "guide.a.s2Title" to "2. Verbinden — optional:",
            "guide.a.s2a" to "Du kannst sofort ohne Konto aufnehmen („Später verbinden“) und die Session später hochladen. Zum Zuordnen: in der Watch-App „Verbinden“ → „Pairing-Code erzeugen“ — den angezeigten Code hier im Tab",
            "guide.a.s2b" to "eintragen.",
            "guide.a.s3Title" to "3. Datenfelder:",
            "guide.a.s3" to "direkt auf der Uhr wischbare Seiten (konfigurierbar im Tab „Datenfelder“). Stopp-Button am Anfang und Ende der Seiten.",
            "guide.a.s4Title" to "4. Aufnehmen:",
            "guide.a.s4" to "App öffnen → Start → foilen → Stop. Aufnahme läuft auch offline; Sync passiert automatisch, sobald online.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. App auf der Uhr installieren:",
            "guide.w.s1" to "den Play Store auf der Uhr öffnen und nach „Pumpfoil“ suchen.",
            "guide.w.s1Note" to "Der Play Store am Handy installiert die Handy-App — die Uhren-App ist eine eigene Installation, direkt auf der Uhr.",
            "guide.w.s2Title" to "2. Verbinden — optional:",
            "guide.w.s2a" to "wie bei Apple Watch — ohne Konto aufnehmen möglich, später verbinden; oder in der Uhr-App „Verbinden“ → „Pairing-Code erzeugen“ und den Code hier im Tab",
            "guide.w.s2b" to "eintragen.",
            "guide.w.s3Title" to "3. Datenfelder:",
            "guide.w.s3" to "wischbare Seiten, konfigurierbar im Tab „Datenfelder“.",
            "guide.w.s4Title" to "4. Aufnehmen:",
            "guide.w.s4" to "App öffnen → Start → foilen → Stop. Offline-Aufnahme + automatischer Sync.",
            "guide.amazfitSub" to "Unser Recorder läuft auf Amazfit-Uhren mit Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 u. a.).",
            "guide.z.store" to "Hol die Zepp-App und finde Pumpfoil in deren integriertem App Store:",
            "guide.z.s1" to "Installiere die Zepp-App (oben) und verbinde deine Amazfit dort wie gewohnt.",
            "guide.z.s2" to "In der Zepp-App: Profil → deine Amazfit → App Store → „Pumpfoil“ suchen → Installieren.",
            "guide.z.s3" to "Öffne Pumpfoil auf der Uhr, wische zu ›Verbinden‹ für einen Code und gib ihn ein unter ",
            "guide.z.s4" to "Drücke START zum Aufzeichnen. GPS und Puls werden automatisch über WLAN/Telefon hochgeladen.",
            "guide.huaweiSub" to "Unser Recorder läuft auf der HUAWEI WATCH 5 (HarmonyOS 5/6). Nach dem Koppeln lädt die Uhr selber hoch – ganz ohne Handy-App.",
            "guide.h.s1" to "Mach auf der Uhr die AppGallery auf, such „Pumpfoil“ und installier die App. Erlaub Standort und Körpersensoren.",
            "guide.h.s2" to "Mach Pumpfoil auf, wisch hinauf zu den Einstellungen und tipp auf ›pumpfoil.org‹ – die Uhr zeigt einen Code. Gib ihn ein unter ",
            "guide.h.s3" to "Tipp auf START. STOPP und Pause 2 Sekunden halten, Verwerfen zweimal tippen.",
            "guide.h.s4" to "Nach dem Stopp lädt die Uhr selber hoch, sobald sie Internet hat (WLAN oder übers gekoppelte Handy). Dann steht „All sent“ am Startbildschirm.",
            "guide.preview" to "So sieht's auf der Uhr aus:",
            "guide.previewVer" to "So sieht's auf der Uhr aus (v1.0.24):",
