            "guide.settings.title" to "Einstellungen für deine Uhr",
            "guide.settings.intro" to "Sobald die Uhr verbunden ist, findest du unter ",
            "guide.settings.intro2" to " zu jeder Uhr zwei Regler. Sie wirken auf die Uhr selbst — sie übernimmt sie beim nächsten Start der App, ohne Update. Wenn dir die Akkulaufzeit wichtig ist, sind das die Stellschrauben.",
            "guide.settings.recordTitle" to "Aufzeichnungsmodus (alle Uhren):",
            "guide.settings.record" to "25 Hz, 10 Hz oder nur GPS. 10 Hz spart Akku und kostet fast nichts — wir haben beide Raten über dieselben Sessions gerechnet: der Pump-Zähler weicht um weniger als ein halbes Prozent ab, und welche Abschnitte als Foilen zählen, ist zu 99,9 % identisch.",
            "guide.settings.gnssTitle" to "Satellitensysteme (nur Garmin):",
            "guide.settings.gnss" to "Voreingestellt ist die beste Stufe, die deine Uhr kann — alle Systeme über zwei Frequenzbänder. Die findet die Position am schnellsten und hält sie am besten, kostet aber deutlich Akku. „Ohne zweites Frequenzband“ behält alle Systeme und lässt nur das teure Extraband weg: der größte Spareffekt bei kleinstem Verlust.",
            "guide.settings.gpsWarn" to "Nur GPS spart am meisten, wirft aber Pump-Zähler, Kadenz und Gleitphasen komplett weg — also genau die Zahlen, für die diese App da ist. Wähle es nur, wenn deine Uhr sonst nicht durchhält.",
            "guide.settings.zepp" to "Bei Amazfit wirkt der Aufzeichnungsmodus noch nicht — die Uhr nimmt mit ihrer eigenen Rate auf. Sprache, Pausenansicht und eigene Layouts holt sie sich dagegen von hier.",
            "watches.title" to "Unterstützte Uhren",
            "watches.intro" to "Wöche Uhr liefert wöche Daten — du entscheidest. Mir wolln langfristig olle gängigen Sportuhren aunbinden.",
            "watches.colDevice" to "Uhr",
            "watches.colGps" to "GPS · Distanz · Speed",
            "watches.colHr" to "Puls",
            "watches.colPump" to "Pumps & Gleitphasen",
            "watches.colStatus" to "Status",
            "watches.foot" to "Pumps & Gleitphasen brauchn Roh-Beschleunigung (≥25 Hz) direkt vo da Uhr. GPS-Stats lassn si bei vüle Marken aa per FIT-/Datenimport auswertn.",
            "watches.legYes" to "voll unterstützt",
            "watches.legPartial" to "eingeschränkt",
            "watches.legNo" to "nicht verfügbar",
            "watches.linkAccount" to "Konto Verknüpfung verfügbar",
            "watches.linkViaSuunto" to "über Mi Fitness → Suunto",
            "watches.nGarmin" to "Ältere Modelle ohne Roh-Accel: GPS-Stats werden trotzdem ausgewertet.",
            "watches.nApple" to "Roh-Beschleunigung über Core Motion.",
            "watches.nWear" to "Läuft auf jeder Wear-OS-3+-Uhr — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Sensor-Zugriff je nach Modell.",
            "watches.nHuaweiW5" to "Lädt nach dem Koppeln per Code selber hoch, ohne Handy-App. Neu in der AppGallery.",
            "watches.nHuawei" to "In Arbeit: Aufnahme auf der Uhr, Übertragung über die Pumpfoil-App auf einem Android-Handy. Welche Daten die Uhren liefern, muss noch getestet werden.",
            "watches.nPolar" to "Konto verknüpfen → Trainings importieren (GPS + HR). Den hochfrequenten Accel-Stream für die Pump-Erkennung liefert der API-Export net (nur via separatem BLE-Sensor).",
            "watches.nSuunto" to "Konto verknüpfen → Trainings importieren (GPS + HR). Den hochfrequenten Accel-Stream für die Pump-Erkennung liefert der FIT-Export (no) net.",
            "watches.nXiaomi" to "Kane App auf da Uhr möglich (Xiaomi lasst kane fremden Apps zua). Dafür schickt Mi Fitness deine Trainings offiziell in die Suunto-App — verknüpf Suunto und sie landen bei uns. Anleitung unter „Konten verknüpfen“.",
            "watches.nFitbit" to "Drittanbieter-Apps wurden eingestellt.",
            "watches.nStrava" to "Import wär technisch machbar, liefert per API aber kein hochfrequentes Roh-Accel (also keine Pump-Erkennung) und steht hinter Paywall + API-Auflagen, die nicht zum offenen Projekt passen — daher bewusst nicht integriert.",
            "watches.subStrava" to "Aktivitäts-Portal",
