            "settings.garmin.help2" to "Water sports and kiteboarding come in automatically. Snow profiles (for example skiing) and “Other” appear below to choose from once the first activity with them has arrived – switch them on if you use them for snowkiting or landkiting.",
            "settings.garmin.help3" to "Recordings with our Pumpfoil app on the watch still come in directly and are not imported twice. Only they count pumps – Garmin does not provide raw accelerometer data.",
