            "guide.a.s1Title" to "1. Install the app:",
            "guide.a.s1" to "from the App Store.",
            "guide.a.s2Title" to "2. Connect — optional:",
            "guide.a.s2a" to "You can record immediately without an account (“Connect later”) and upload the session afterwards. To link it: in the watch app “Connect” → “Generate pairing code” — enter the shown code here in the tab",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Data fields:",
            "guide.a.s3" to "swipeable pages right on the watch (configurable in the “Data fields” tab). Stop button at the start and end of the pages.",
            "guide.a.s4Title" to "4. Record:",
            "guide.a.s4" to "open the app → Start → foil → Stop. Recording also works offline; sync happens automatically once online.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Install the app on the watch:",
            "guide.w.s1" to "open the Play Store on the watch and search for “Pumpfoil”.",
            "guide.w.s1Note" to "The Play Store on your phone installs the phone app — the watch app is a separate install, on the watch itself.",
            "guide.w.s2Title" to "2. Connect — optional:",
            "guide.w.s2a" to "like Apple Watch — recording without an account is possible, connect later; or in the watch app “Connect” → “Generate pairing code” and enter the code here in the tab",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Data fields:",
