            "guide.w.s4Title" to "4. Record:",
            "guide.w.s4" to "open the app → Start → foil → Stop. Offline recording + automatic sync.",
            "guide.amazfitSub" to "Our recorder runs on Amazfit watches with Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 and more).",
            "guide.z.store" to "Get the Zepp app, then find Pumpfoil in its built-in App Store:",
            "guide.z.s1" to "Install the Zepp app (above) and pair your Amazfit in it as usual.",
            "guide.z.s2" to "In the Zepp app: Profile → your Amazfit → App Store → search “Pumpfoil” → Install.",
            "guide.z.s3" to "Open Pumpfoil on the watch, swipe to ›Connect‹ for a code, then enter it under ",
            "guide.z.s4" to "Press START to record. GPS and heart rate upload automatically over Wi-Fi or your phone.",
            "guide.huaweiSub" to "Our recorder runs on the HUAWEI WATCH 5 (HarmonyOS 5/6). Once linked, the watch uploads on its own – no phone app needed.",
            "guide.h.s1" to "On the watch, open AppGallery, search for “Pumpfoil” and install it. Allow location and body sensors.",
            "guide.h.s2" to "Open Pumpfoil, swipe up to the settings and tap ›pumpfoil.org‹ – the watch shows a code. Enter it under ",
            "guide.h.s3" to "Tap START. Hold STOP and Pause for 2 seconds, tap Discard twice.",
            "guide.h.s4" to "After stopping, the watch uploads on its own as soon as it has internet (Wi-Fi or via the paired phone). The start screen then shows “All sent”.",
