            "guide.cap.wRun" to "Current run",
            "guide.cap.wStop" to "Hold → stop",
            "guide.cap.aConnect" to "Connect — generate code",
            "guide.cap.aCode" to "Code → on pumpfoil.org",
            "guide.cap.aStart" to "Start",
            "guide.cap.aAlarm" to "Choose alarm + trigger",
            "guide.cap.aStop" to "Stop",
            "guide.cap.aUpload" to "Upload after stopping",
            "guide.settings.title" to "Settings for your watch",
            "guide.settings.intro" to "Once the watch is connected, you will find two controls for each of them under ",
            "guide.settings.intro2" to ". They act on the watch itself — it picks them up the next time you open the app there, no update needed. If battery life matters to you, these are the levers.",
            "guide.settings.recordTitle" to "Recording mode (all watches):",
            "guide.settings.record" to "25 Hz, 10 Hz or GPS only. 10 Hz saves battery and costs almost nothing — we ran both rates over the same sessions: your pump count lands within half a percent, and which parts count as foiling is 99.9% identical.",
            "guide.settings.gnssTitle" to "Satellite systems (Garmin only):",
            "guide.settings.gnss" to "The default is the best your watch can manage — every system across two frequency bands. That finds your position fastest and holds onto it best, but it costs real battery. “Without second frequency band” keeps every system and drops only the costly extra band: the most saved for the least lost.",
            "guide.settings.gpsWarn" to "GPS only saves the most, but it throws away pump count, cadence and glide phases altogether — exactly the numbers this app exists for. Pick it only if your watch otherwise will not last the session.",
            "guide.settings.zepp" to "On Amazfit the recording mode has no effect yet — the watch records at its own rate. It does take its language, pause view and custom layouts from here.",
            "watches.title" to "Supported watches",
            "watches.intro" to "Which watch gives which data — you decide. Long-term we want to support all common sports watches.",
            "watches.colDevice" to "Watch",
            "watches.colGps" to "GPS · distance · speed",
            "watches.colHr" to "Heart rate",
            "watches.colPump" to "Pumps & glide phases",
            "watches.colStatus" to "Status",
            "watches.foot" to "Pumps & glide phases need raw acceleration (≥25 Hz) straight from the watch. GPS stats can be analyzed via FIT/data import for many brands.",
            "watches.legYes" to "fully supported",
            "watches.legPartial" to "limited",
            "watches.legNo" to "not available",
            "watches.linkAccount" to "Account linking available",
            "watches.linkViaSuunto" to "via Mi Fitness → Suunto",
            "watches.nGarmin" to "Older models without raw accel: GPS stats are still analyzed.",
            "watches.nApple" to "Raw acceleration via Core Motion.",
            "watches.nWear" to "Runs on any Wear OS 3+ watch — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Sensor access depends on the model.",
            "watches.nHuaweiW5" to "Uploads on its own after linking with a code, no phone app needed. New on AppGallery.",
            "watches.nHuawei" to "In progress: records on the watch, transfers via the Pumpfoil app on an Android phone. Which data the watches deliver still needs testing.",
            "watches.nPolar" to "Link your account → import workouts (GPS + HR). The API export doesn't include the high-rate raw accel stream needed for pump detection (only via a separate BLE sensor).",
            "watches.nSuunto" to "Link your account → import workouts (GPS + HR). The FIT export doesn't (yet) include the high-rate raw accel stream needed for pump detection.",
            "watches.nXiaomi" to "No app on the watch (Xiaomi allows no third-party apps). But Mi Fitness officially pushes your workouts into the Suunto app — link Suunto and they arrive here. Instructions under “Linked accounts”.",
            "watches.nFitbit" to "Third-party apps were discontinued.",
            "watches.nStrava" to "An import would be technically possible, but the API does not provide high-rate raw accelerometer data (so no pump detection), and it sits behind a paywall plus API terms that do not fit an open project — deliberately not integrated.",
            "watches.subStrava" to "activity portal",
