            "brett.erkl.titel" to "Qu'est-ce que l'assiette de la planche ?",
            "brett.erkl.was" to "Si ton téléphone est fixé sur la planche pendant la session, son gyroscope mesure comment la planche tangue et roule – directement à la source plutôt qu'au poignet.",
            "brett.erkl.wie" to "Comment faire : mets ton téléphone dans une pochette étanche, fixe-le à plat sur le pont et lance l'enregistrement dans l'app Pumpfoil sur le téléphone. Ta montre peut enregistrer en même temps. L'analyse détecte en général toute seule que le téléphone était sur la planche.",
            "brett.erkl.bringt" to "Ce que ça t'apporte : tu vois à quel point ta planche reste stable en pumpant, combien elle tangue et roule à chaque pump, et si cela change selon le foil, dans les virages ou en ligne droite. Chaque enregistrement de ce type aide aussi à améliorer la détection des pumps pour la montre.",
            "brett.erkl.daten" to "Les données obtenues : tangage et roulis par pump, inclinaison, cadence, virages contre lignes droites et le mouvement vertical (dès que le rythme de pump est détecté de façon fiable) – par run, et ici en vue d'ensemble de tous les runs et par foil.",
