            "guide.a.s1Title" to "1. Installer l'app :",
            "guide.a.s1" to "depuis l'App Store.",
            "guide.a.s2Title" to "2. Connecter — optionnel :",
            "guide.a.s2a" to "Tu peux enregistrer immédiatement sans compte (« Connecter plus tard ») et envoyer la session ensuite. Pour la lier : dans l'app de la montre « Connecter » → « Générer un code » — saisis le code affiché ici dans l'onglet",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Champs de données :",
            "guide.a.s3" to "pages glissables directement sur la montre (configurables dans l'onglet « Champs de données »). Bouton Stop au début et à la fin des pages.",
            "guide.a.s4Title" to "4. Enregistrer :",
            "guide.a.s4" to "ouvre l'app → Démarrer → foile → Stop. L'enregistrement fonctionne aussi hors ligne ; la synchro se fait automatiquement une fois en ligne.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Installer l'app sur la montre :",
            "guide.w.s1" to "ouvrir le Play Store sur la montre et chercher « Pumpfoil ».",
            "guide.w.s1Note" to "Le Play Store du téléphone installe l'app téléphone — l'app montre s'installe séparément, sur la montre elle-même.",
            "guide.w.s2Title" to "2. Connecter — optionnel :",
            "guide.w.s2a" to "comme l'Apple Watch — enregistrement sans compte possible, connecter plus tard ; ou dans l'app de la montre « Connecter » → « Générer un code » et saisis le code ici dans l'onglet",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Champs de données :",
            "guide.w.s3" to "pages glissables, configurables dans l'onglet « Champs de données ».",
            "guide.w.s4Title" to "4. Enregistrer :",
            "guide.w.s4" to "ouvre l'app → Démarrer → foile → Stop. Enregistrement hors ligne + synchro automatique.",
            "guide.amazfitSub" to "Notre enregistreur fonctionne sur les montres Amazfit sous Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3, etc.).",
            "guide.z.store" to "Installe l’app Zepp, puis trouve Pumpfoil dans son App Store intégré :",
            "guide.z.s1" to "Installe l’app Zepp (ci-dessus) et associe ta montre Amazfit comme d’habitude.",
            "guide.z.s2" to "Dans l’app Zepp : Profil → ta Amazfit → App Store → cherche « Pumpfoil » → Installer.",
            "guide.z.s3" to "Ouvre Pumpfoil sur la montre, glisse vers ›Connecter‹ pour obtenir un code, puis saisis-le sous ",
            "guide.z.s4" to "Appuie sur START pour enregistrer. GPS et fréquence cardiaque sont envoyés automatiquement via Wi-Fi/téléphone.",
            "guide.huaweiSub" to "Notre enregistreur fonctionne sur la HUAWEI WATCH 5 (HarmonyOS 5/6). Une fois associée, la montre envoie elle-même ses données – sans appli sur le téléphone.",
            "guide.h.s1" to "Sur la montre, ouvre AppGallery, cherche « Pumpfoil » et installe l’appli. Autorise la localisation et les capteurs corporels.",
            "guide.h.s2" to "Ouvre Pumpfoil, balaie vers le haut jusqu’aux réglages et touche ›pumpfoil.org‹ – la montre affiche un code. Saisis-le sous ",
            "guide.h.s3" to "Touche START. Maintiens STOP et Pause 2 secondes, touche Supprimer deux fois.",
            "guide.h.s4" to "Après l’arrêt, la montre envoie elle-même dès qu’elle a Internet (Wi-Fi ou via le téléphone associé). L’écran d’accueil affiche alors « All sent ».",
            "guide.preview" to "Aperçu sur la montre :",
