            "guide.settings.title" to "Réglages pour ta montre",
            "guide.settings.intro" to "Une fois la montre connectée, tu trouveras deux réglages pour chacune sous ",
            "guide.settings.intro2" to ". Ils agissent sur la montre elle-même — elle les récupère à la prochaine ouverture de l'application, aucune mise à jour nécessaire. Si l'autonomie compte pour toi, ce sont les leviers.",
            "guide.settings.recordTitle" to "Mode d'enregistrement (toutes les montres) :",
            "guide.settings.record" to "25 Hz, 10 Hz ou GPS seul. 10 Hz économise la batterie et ne coûte presque rien — nous avons passé les deux fréquences sur les mêmes sessions : ton comptage de pompages tombe à un demi pour cent près, et les portions comptées comme foiling sont identiques à 99,9 %.",
            "guide.settings.gnssTitle" to "Systèmes satellitaires (Garmin uniquement) :",
            "guide.settings.gnss" to "Par défaut, c'est le meilleur que ta montre sache faire — tous les systèmes sur deux bandes de fréquence. C'est ce qui trouve ta position le plus vite et la garde le mieux, mais ça coûte vraiment de la batterie. « Sans deuxième bande de fréquence » garde tous les systèmes et n'abandonne que la bande supplémentaire coûteuse : le plus économisé pour le moins perdu.",
            "guide.settings.gpsWarn" to "GPS seul économise le plus, mais supprime complètement le comptage des pompages, la cadence et les phases de glisse — précisément les chiffres pour lesquels cette application existe. Ne le choisis que si ta montre ne tient pas la session autrement.",
            "guide.settings.zepp" to "Sur Amazfit, le mode d'enregistrement n'a pas encore d'effet — la montre enregistre à sa propre fréquence. Elle prend en revanche sa langue, sa vue de pause et tes mises en page perso ici.",
            "watches.title" to "Montres prises en charge",
            "watches.intro" to "Quelle montre fournit quelles données — à toi de choisir. À terme, nous voulons prendre en charge toutes les montres de sport courantes.",
            "watches.colDevice" to "Montre",
            "watches.colGps" to "GPS · distance · vitesse",
            "watches.colHr" to "Fréq. cardiaque",
            "watches.colPump" to "Pompages & glisse",
            "watches.colStatus" to "Statut",
            "watches.foot" to "Les pompages & phases de glisse nécessitent l'accélération brute (≥25 Hz) directement depuis la montre. Les stats GPS peuvent s'analyser via import FIT/données pour de nombreuses marques.",
            "watches.legYes" to "entièrement pris en charge",
            "watches.legPartial" to "limité",
            "watches.legNo" to "non disponible",
            "watches.linkAccount" to "Liaison de compte disponible",
            "watches.linkViaSuunto" to "via Mi Fitness → Suunto",
            "watches.nGarmin" to "Modèles plus anciens sans accel brut : les stats GPS sont quand même analysées.",
            "watches.nApple" to "Accélération brute via Core Motion.",
            "watches.nWear" to "Fonctionne sur toute montre Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Accès aux capteurs selon le modèle.",
            "watches.nHuaweiW5" to "Envoie elle-même après association par code, sans appli sur le téléphone. Nouveau sur AppGallery.",
            "watches.nHuawei" to "En cours : enregistrement sur la montre, transfert via l’appli Pumpfoil sur un téléphone Android. Les données fournies par chaque montre restent à tester.",
            "watches.nPolar" to "Lier le compte → importer les entraînements (GPS + FC). L'export API ne fournit pas le flux accel brut haute fréquence requis pour la détection de pump (seulement via un capteur BLE séparé).",
            "watches.nSuunto" to "Lier le compte → importer les entraînements (GPS + FC). L'export FIT ne fournit pas (encore) le flux accel brut haute fréquence requis pour la détection de pump.",
            "watches.nXiaomi" to "Pas d'app sur la montre (Xiaomi n'autorise pas les apps tierces). En revanche Mi Fitness envoie officiellement tes entraînements dans l'app Suunto — connecte Suunto et ils arrivent ici. Voir « Comptes liés ».",
            "watches.nFitbit" to "Les apps tierces ont été abandonnées.",
            "watches.nStrava" to "Un import serait techniquement possible, mais l'API ne fournit pas de données brutes d'accéléromètre à haute fréquence (donc pas de détection des pompages), et elle est derrière un paywall avec des conditions d'API qui ne conviennent pas à un projet ouvert — délibérément non intégré.",
            "watches.subStrava" to "portail d'activités",
            "watches.st.avail" to "Disponible",
            "watches.st.planned" to "en attente d’approbation",
            "watches.st.import" to "Polar API",
