            "sessions.uploadReplaceAsk" to "Questa uscita c’è già (sessione #{id}), ma il file è diverso. Eliminare la vecchia sessione e sostituirla con questo file?\n\nPer accorciarla basta «{trim}» nella sessione, senza un nuovo file.",
            "team.regeln.haftung.titel" to "Responsabilità",
            "team.regeln.haftung.text" to "Gli eventi sono organizzati dai team stessi. pumpfoil.org non ha alcuna influenza sugli eventi né sulle promesse fatte al loro interno, economiche o di altro tipo, e non se ne assume alcuna responsabilità. È escluso il ricorso alle vie legali. Pagamenti e ogni altro accordo si regolano tra organizzatori e partecipanti, indipendentemente da pumpfoil.org.\nAllo stesso modo, pumpfoil.org non si assume alcuna responsabilità sulla correttezza dei valori e dei dati misurati o sulla loro eventuale manipolazione. Viene mostrato ciò che il codice sorgente pubblico su GitHub calcola dai dati caricati; non ci sono altre garanzie.",
