            "guide.appleSub" to "watchOS 9+",
            "guide.a.s1Title" to "1. Installa l'app:",
            "guide.a.s1" to "dall'App Store.",
            "guide.a.s2Title" to "2. Connetti — facoltativo:",
            "guide.a.s2a" to "Puoi registrare subito senza account (« Connetti più tardi ») e caricare la sessione in seguito. Per collegarla: nell'app dell'orologio « Connetti » → « Genera codice » — inserisci il codice mostrato qui nella scheda",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Campi dati:",
            "guide.a.s3" to "pagine scorrevoli direttamente sull'orologio (configurabili nella scheda « Campi dati »). Pulsante Stop all'inizio e alla fine delle pagine.",
            "guide.a.s4Title" to "4. Registra:",
            "guide.a.s4" to "apri l'app → Avvia → foila → Stop. La registrazione funziona anche offline; la sincronizzazione avviene automaticamente una volta online.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Installa l'app sull'orologio:",
            "guide.w.s1" to "apri il Play Store sull'orologio e cerca «Pumpfoil».",
            "guide.w.s1Note" to "Il Play Store sul telefono installa l'app per telefono — l'app per orologio è un'installazione separata, sull'orologio stesso.",
            "guide.w.s2Title" to "2. Connetti — facoltativo:",
            "guide.w.s2a" to "come Apple Watch — registrazione senza account possibile, connetti più tardi; oppure nell'app dell'orologio « Connetti » → « Genera codice » e inserisci il codice qui nella scheda",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Campi dati:",
            "guide.w.s3" to "pagine scorrevoli, configurabili nella scheda « Campi dati ».",
            "guide.w.s4Title" to "4. Registra:",
            "guide.w.s4" to "apri l'app → Avvia → foila → Stop. Registrazione offline + sincronizzazione automatica.",
            "guide.amazfitSub" to "Il nostro registratore funziona su orologi Amazfit con Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 e altri).",
            "guide.z.store" to "Installa l’app Zepp, poi trova Pumpfoil nel suo App Store integrato:",
            "guide.z.s1" to "Installa l’app Zepp (sopra) e associa il tuo Amazfit come al solito.",
            "guide.z.s2" to "Nell’app Zepp: Profilo → il tuo Amazfit → App Store → cerca «Pumpfoil» → Installa.",
            "guide.z.s3" to "Apri Pumpfoil sull’orologio, scorri fino a ›Connetti‹ per un codice, poi inseriscilo in ",
            "guide.z.s4" to "Premi START per registrare. GPS e battito vengono caricati automaticamente via Wi-Fi/telefono.",
            "guide.huaweiSub" to "Il nostro registratore funziona su HUAWEI WATCH 5 (HarmonyOS 5/6). Una volta collegato, l’orologio carica da solo – senza app sul telefono.",
            "guide.h.s1" to "Sull’orologio apri AppGallery, cerca “Pumpfoil” e installa l’app. Consenti posizione e sensori corporei.",
            "guide.h.s2" to "Apri Pumpfoil, scorri in alto fino alle impostazioni e tocca ›pumpfoil.org‹ – l’orologio mostra un codice. Inseriscilo in ",
            "guide.h.s3" to "Tocca START. Tieni premuti STOP e Pausa per 2 secondi, tocca Scarta due volte.",
            "guide.h.s4" to "Dopo lo stop l’orologio carica da solo appena ha Internet (Wi-Fi o tramite il telefono collegato). Sulla schermata iniziale compare “All sent”.",
            "guide.preview" to "Anteprima sull'orologio:",
            "guide.previewVer" to "Anteprima sull'orologio (v1.0.24):",
