            "guide.settings.title" to "Impostazioni per il tuo orologio",
            "guide.settings.intro" to "Una volta collegato l'orologio, per ciascuno trovi due comandi sotto ",
            "guide.settings.intro2" to ". Agiscono sull'orologio stesso — li recepisce alla prossima apertura dell'app, nessun aggiornamento necessario. Se l'autonomia ti sta a cuore, sono queste le leve.",
            "guide.settings.recordTitle" to "Modalità di registrazione (tutti gli orologi):",
            "guide.settings.record" to "25 Hz, 10 Hz o solo GPS. 10 Hz risparmia batteria e non costa quasi nulla — abbiamo fatto girare entrambe le frequenze sulle stesse sessioni: il conteggio delle pompate resta entro mezzo percento, e quali parti contano come foiling è identico al 99,9 %.",
            "guide.settings.gnssTitle" to "Sistemi satellitari (solo Garmin):",
            "guide.settings.gnss" to "Di base è il meglio che il tuo orologio sa fare — tutti i sistemi su due bande di frequenza. È così che trova la posizione più in fretta e la tiene meglio, ma costa parecchia batteria. «Senza seconda banda di frequenza» mantiene tutti i sistemi e rinuncia solo alla costosa banda aggiuntiva: il massimo risparmio con la minima perdita.",
            "guide.settings.gpsWarn" to "Solo GPS risparmia di più, ma butta via del tutto conteggio delle pompate, cadenza e fasi di planata — proprio i numeri per cui questa app esiste. Sceglilo solo se altrimenti l'orologio non regge la sessione.",
            "guide.settings.zepp" to "Su Amazfit la modalità di registrazione non ha ancora effetto — l'orologio registra alla propria frequenza. Prende invece da qui lingua, vista di pausa e layout personalizzati.",
            "watches.title" to "Orologi supportati",
            "watches.intro" to "Quale orologio fornisce quali dati — decidi tu. A lungo termine vogliamo supportare tutti i principali sportwatch.",
            "watches.colDevice" to "Orologio",
            "watches.colGps" to "GPS · distanza · velocità",
            "watches.colHr" to "Battito",
            "watches.colPump" to "Pompate & planata",
            "watches.colStatus" to "Stato",
            "watches.foot" to "Pompate & fasi di planata richiedono l'accelerazione grezza (≥25 Hz) direttamente dall'orologio. Le statistiche GPS si possono analizzare via import FIT/dati per molti marchi.",
            "watches.legYes" to "pieno supporto",
            "watches.legPartial" to "limitato",
            "watches.legNo" to "non disponibile",
            "watches.linkAccount" to "Collegamento account disponibile",
            "watches.linkViaSuunto" to "tramite Mi Fitness → Suunto",
            "watches.nGarmin" to "Modelli più vecchi senza accel grezzo: le statistiche GPS vengono comunque analizzate.",
            "watches.nApple" to "Accelerazione grezza via Core Motion.",
            "watches.nWear" to "Funziona su qualsiasi orologio Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Accesso ai sensori a seconda del modello.",
            "watches.nHuaweiW5" to "Carica da solo dopo il collegamento con un codice, senza app sul telefono. Nuovo su AppGallery.",
            "watches.nHuawei" to "In lavorazione: registrazione sull’orologio, trasferimento tramite l’app Pumpfoil su un telefono Android. Quali dati forniscono gli orologi è ancora da testare.",
            "watches.nPolar" to "Collega l'account → importa allenamenti (GPS + FC). L'export API non include il flusso accel grezzo ad alta frequenza per il rilevamento del pump (solo con sensore BLE separato).",
            "watches.nSuunto" to "Collega l'account → importa allenamenti (GPS + FC). L'export FIT non include (ancora) il flusso accel grezzo ad alta frequenza per il rilevamento del pump.",
            "watches.nXiaomi" to "Nessuna app sull'orologio (Xiaomi non consente app di terze parti). Però Mi Fitness invia ufficialmente i tuoi allenamenti all'app Suunto — collega Suunto e arrivano qui. Istruzioni in «Account collegati».",
            "watches.nFitbit" to "Le app di terze parti sono state dismesse.",
            "watches.nStrava" to "Un import sarebbe tecnicamente possibile, ma l'API non fornisce dati grezzi dell'accelerometro ad alta frequenza (quindi niente rilevamento delle pompate) e sta dietro un paywall con condizioni d'uso che non si adattano a un progetto aperto — deliberatamente non integrato.",
            "watches.subStrava" to "portale di attività",
