            "sessions.uploadReplaceAsk" to "Esta sesión ya existe (sesión #{id}), pero el archivo es distinto. ¿Borrar la sesión antigua y sustituirla por este archivo?\n\nPara solo recortarla no hace falta un archivo nuevo: usa «{trim}» en la sesión.",
            "team.regeln.haftung.titel" to "Responsabilidad",
            "team.regeln.haftung.text" to "Los eventos los organizan los propios equipos. pumpfoil.org no tiene ninguna influencia sobre los eventos ni sobre las promesas que se hagan en ellos, económicas o de otro tipo, y no asume ninguna responsabilidad. Queda excluida la vía judicial. Los pagos y cualquier otro acuerdo los resuelven organizadores y participantes, independientemente de pumpfoil.org.\nDel mismo modo, pumpfoil.org no asume ninguna responsabilidad sobre si los valores y datos medidos son correctos o han sido manipulados. Se muestra lo que el código fuente público en GitHub calcula a partir de los datos subidos; no hay más promesas.",
