            "guide.appleSub" to "watchOS 9+",
            "guide.a.s1Title" to "1. Instalar la app:",
            "guide.a.s1" to "desde la App Store.",
            "guide.a.s2Title" to "2. Conectar — opcional:",
            "guide.a.s2a" to "Puedes grabar de inmediato sin cuenta (« Conectar más tarde ») y subir la sesión después. Para vincularla: en la app del reloj « Conectar » → « Generar código » — introduce el código mostrado aquí en la pestaña",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Campos de datos:",
            "guide.a.s3" to "páginas deslizables directamente en el reloj (configurables en la pestaña « Campos de datos »). Botón Stop al principio y al final de las páginas.",
            "guide.a.s4Title" to "4. Grabar:",
            "guide.a.s4" to "abre la app → Iniciar → foilea → Stop. La grabación también funciona sin conexión; la sincronización se hace automáticamente al estar en línea.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Instalar la app en el reloj:",
            "guide.w.s1" to "abre la Play Store en el reloj y busca «Pumpfoil».",
            "guide.w.s1Note" to "La Play Store del móvil instala la app del móvil — la app del reloj se instala aparte, en el propio reloj.",
            "guide.w.s2Title" to "2. Conectar — opcional:",
            "guide.w.s2a" to "como Apple Watch — se puede grabar sin cuenta, conectar más tarde; o en la app del reloj « Conectar » → « Generar código » e introduce el código aquí en la pestaña",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Campos de datos:",
            "guide.w.s3" to "páginas deslizables, configurables en la pestaña « Campos de datos ».",
            "guide.w.s4Title" to "4. Grabar:",
            "guide.w.s4" to "abre la app → Iniciar → foilea → Stop. Grabación sin conexión + sincronización automática.",
            "guide.amazfitSub" to "Nuestro grabador funciona en relojes Amazfit con Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 y más).",
            "guide.z.store" to "Instala la app Zepp y luego busca Pumpfoil en su App Store integrada:",
            "guide.z.s1" to "Instala la app Zepp (arriba) y vincula tu Amazfit como de costumbre.",
            "guide.z.s2" to "En la app Zepp: Perfil → tu Amazfit → App Store → busca «Pumpfoil» → Instalar.",
            "guide.z.s3" to "Abre Pumpfoil en el reloj, desliza hasta ›Conectar‹ para un código y escríbelo en ",
            "guide.z.s4" to "Pulsa START para grabar. El GPS y el pulso se suben automáticamente por Wi-Fi/teléfono.",
            "guide.huaweiSub" to "Nuestro grabador funciona en el HUAWEI WATCH 5 (HarmonyOS 5/6). Una vez vinculado, el reloj sube los datos por sí solo, sin app en el móvil.",
            "guide.h.s1" to "En el reloj, abre AppGallery, busca «Pumpfoil» e instala la app. Permite ubicación y sensores corporales.",
            "guide.h.s2" to "Abre Pumpfoil, desliza hacia arriba hasta los ajustes y toca ›pumpfoil.org‹: el reloj muestra un código. Introdúcelo en ",
            "guide.h.s3" to "Toca START. Mantén STOP y Pausa 2 segundos, toca Descartar dos veces.",
            "guide.h.s4" to "Tras parar, el reloj sube los datos por sí solo en cuanto tiene Internet (Wi-Fi o a través del móvil vinculado). La pantalla de inicio muestra entonces «All sent».",
            "guide.preview" to "Vista previa en el reloj:",
