            "guide.settings.title" to "Ajustes para tu reloj",
            "guide.settings.intro" to "Una vez conectado el reloj, encontrarás dos controles para cada uno bajo ",
            "guide.settings.intro2" to ". Actúan sobre el propio reloj — los recoge la próxima vez que abras la app allí, sin necesidad de actualizar. Si la autonomía te importa, estas son las palancas.",
            "guide.settings.recordTitle" to "Modo de grabación (todos los relojes):",
            "guide.settings.record" to "25 Hz, 10 Hz o solo GPS. 10 Hz ahorra batería y casi no cuesta nada — pasamos ambas frecuencias por las mismas sesiones: tu recuento de bombeos queda dentro de medio por ciento, y qué partes cuentan como foiling es idéntico al 99,9 %.",
            "guide.settings.gnssTitle" to "Sistemas de satélites (solo Garmin):",
            "guide.settings.gnss" to "Por defecto es lo mejor que tu reloj sabe hacer — todos los sistemas en dos bandas de frecuencia. Así encuentra tu posición más rápido y la mantiene mejor, pero cuesta batería de verdad. «Sin segunda banda de frecuencia» mantiene todos los sistemas y solo renuncia a la costosa banda extra: lo que más ahorra perdiendo lo menos.",
            "guide.settings.gpsWarn" to "Solo GPS es lo que más ahorra, pero tira por completo el recuento de bombeos, la cadencia y las fases de planeo — justo los números por los que existe esta app. Elígelo solo si tu reloj no aguanta la sesión de otro modo.",
            "guide.settings.zepp" to "En Amazfit el modo de grabación todavía no tiene efecto — el reloj graba a su propia frecuencia. En cambio sí toma de aquí el idioma, la vista de pausa y tus diseños propios.",
            "watches.title" to "Relojes compatibles",
            "watches.intro" to "Qué reloj da qué datos — tú decides. A largo plazo queremos admitir todos los relojes deportivos habituales.",
            "watches.colDevice" to "Reloj",
            "watches.colGps" to "GPS · distancia · velocidad",
            "watches.colHr" to "Pulso",
            "watches.colPump" to "Bombeos & planeo",
            "watches.colStatus" to "Estado",
            "watches.foot" to "Bombeos & fases de planeo necesitan aceleración bruta (≥25 Hz) directa del reloj. Las estadísticas GPS se pueden analizar vía import FIT/datos en muchas marcas.",
            "watches.legYes" to "totalmente compatible",
            "watches.legPartial" to "limitado",
            "watches.legNo" to "no disponible",
            "watches.linkAccount" to "Vinculación de cuenta disponible",
            "watches.linkViaSuunto" to "vía Mi Fitness → Suunto",
            "watches.nGarmin" to "Modelos antiguos sin accel bruto: las estadísticas GPS se analizan igualmente.",
            "watches.nApple" to "Aceleración bruta vía Core Motion.",
            "watches.nWear" to "Funciona en cualquier reloj Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Acceso a sensores según el modelo.",
            "watches.nHuaweiW5" to "Sube los datos por sí solo tras vincularlo con un código, sin app en el móvil. Nuevo en AppGallery.",
            "watches.nHuawei" to "En desarrollo: grabación en el reloj, transferencia mediante la app Pumpfoil en un móvil Android. Aún hay que probar qué datos da cada reloj.",
            "watches.nPolar" to "Vincula tu cuenta → importa entrenamientos (GPS + FC). La API no expone el flujo de accel bruto de alta frecuencia para detectar pump (solo con un sensor BLE aparte).",
            "watches.nSuunto" to "Vincula tu cuenta → importa entrenamientos (GPS + FC). La exportación FIT no incluye (todavía) el flujo de accel bruto de alta frecuencia para detectar pump.",
            "watches.nXiaomi" to "Sin app en el reloj (Xiaomi no permite apps de terceros). Pero Mi Fitness envía oficialmente tus entrenamientos a la app de Suunto — conecta Suunto y llegan aquí. Instrucciones en «Cuentas vinculadas».",
            "watches.nFitbit" to "Las apps de terceros fueron descontinuadas.",
            "watches.nStrava" to "Una importación sería técnicamente posible, pero la API no entrega datos brutos del acelerómetro a alta frecuencia (o sea, sin detección de bombeos), y está detrás de un muro de pago con condiciones de API que no encajan en un proyecto abierto — deliberadamente no integrado.",
            "watches.subStrava" to "portal de actividades",
