            "brett.erkl.was" to "Kun puhelin on kiinnitetty lautaan session ajaksi, sen gyroskooppi mittaa, miten lauta nyökkää ja kallistuu – suoraan lähteellä eikä ranteessa.",
            "brett.erkl.wie" to "Näin se toimii: laita puhelin vesitiiviiseen koteloon, kiinnitä se tasaisesti kanteen ja aloita tallennus puhelimen Pumpfoil-sovelluksessa. Kello voi tallentaa samaan aikaan. Analyysi huomaa yleensä itse, että puhelin oli laudalla.",
            "brett.erkl.bringt" to "Mitä siitä saat: näet, kuinka vakaasti lauta kulkee pumpatessa, kuinka paljon se nyökkää ja kallistuu jokaisella pumpulla ja eroaako se foilien, kaarteiden ja suorien välillä. Jokainen tällainen tallennus auttaa myös parantamaan kellon pumppujen tunnistusta.",
            "brett.erkl.daten" to "Saamasi tiedot: nyökkäys ja kallistus pumppua kohden, kallistuma, tahti, kaarteet vastaan suorat ja pystyliike (kun pumpputahti tunnistetaan varmasti) – lenkeittäin ja tässä yhteenvetona kaikista lenkeistä ja foileittain.",
