            "team.alleMeine" to "Kaikki tiimini",
            "sessions.uploadReplaceAsk" to "Tämä ajo on jo täällä (sessio #{id}), mutta tiedosto on eri. Poistetaanko vanha sessio ja korvataan se tällä tiedostolla?\n\nPelkkään lyhentämiseen ei tarvita uutta tiedostoa: käytä sessiossa kohtaa ”{trim}”.",
            "team.regeln.haftung.titel" to "Vastuu",
            "team.regeln.haftung.text" to "Tapahtumat järjestävät tiimit itse. pumpfoil.orgilla ei ole vaikutusvaltaa tapahtumiin eikä niissä annettuihin taloudellisiin tai muihin lupauksiin, eikä se ota niistä vastuuta. Oikeustie on suljettu pois. Maksut ja kaikki muut sopimukset järjestäjät ja osallistujat hoitavat keskenään, pumpfoil.orgista riippumatta.\nSamoin pumpfoil.org ei vastaa siitä, ovatko mitatut arvot ja tiedot oikeita tai onko niitä manipuloitu. Näytetään se, minkä GitHubissa oleva julkinen lähdekoodi laskee ladatuista tiedoista; muita lupauksia ei ole.",
