            "guide.appleSub" to "watchOS 9+",
            "guide.a.s1Title" to "1. Asenna sovellus:",
            "guide.a.s1" to "App Storesta.",
            "guide.a.s2Title" to "2. Yhdistä — valinnainen:",
            "guide.a.s2a" to "Voit tallentaa heti ilman tiliä („Yhdistä myöhemmin“) ja ladata session myöhemmin. Liittämiseen: kello-sovelluksessa „Yhdistä“ → „Luo pariutuskoodi“ — syötä näkyvä koodi tässä välilehdellä",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Datakentät:",
            "guide.a.s3" to "suoraan kellossa pyyhkäistävät sivut (säädettävissä välilehdellä „Datakentät“). Pysäytysnappi sivujen alussa ja lopussa.",
            "guide.a.s4Title" to "4. Tallennus:",
            "guide.a.s4" to "Avaa sovellus → Aloita → foilaa → Pysäytä. Tallennus toimii myös offline; synkkaus tapahtuu automaattisesti heti kun verkossa.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Asenna sovellus kelloon:",
            "guide.w.s1" to "avaa Play Store kellossa ja etsi ”Pumpfoil”.",
            "guide.w.s1Note" to "Puhelimen Play Store asentaa puhelinsovelluksen — kellosovellus asennetaan erikseen, itse kellossa.",
            "guide.w.s2Title" to "2. Yhdistä — valinnainen:",
            "guide.w.s2a" to "kuten Apple Watchilla — tallennus ilman tiliä mahdollista, yhdistä myöhemmin; tai kello-sovelluksessa „Yhdistä“ → „Luo pariutuskoodi“ ja syötä koodi tässä välilehdellä",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Datakentät:",
            "guide.w.s3" to "pyyhkäistävät sivut, säädettävissä välilehdellä „Datakentät“.",
            "guide.w.s4Title" to "4. Tallennus:",
            "guide.w.s4" to "Avaa sovellus → Aloita → foilaa → Pysäytä. Offline-tallennus + automaattinen synkkaus.",
            "guide.amazfitSub" to "Tallennin toimii Amazfit-kelloissa, joissa on Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 ym.).",
            "guide.z.store" to "Asenna Zepp-sovellus ja etsi Pumpfoil sen App Storesta:",
            "guide.z.s1" to "Asenna Zepp-sovellus (yllä) ja yhdistä Amazfit siihen tavalliseen tapaan.",
            "guide.z.s2" to "Zepp-sovelluksessa: Profiili → Amazfit → App Store → hae „Pumpfoil“ → Asenna.",
            "guide.z.s3" to "Avaa Pumpfoil kellossa, pyyhkäise kohtaan ›Yhdistä‹ saadaksesi koodin ja syötä se kohtaan ",
            "guide.z.s4" to "Aloita tallennus painamalla START. GPS ja syke lähetetään automaattisesti Wi-Fin/puhelimen kautta.",
            "guide.huaweiSub" to "Tallentimemme toimii HUAWEI WATCH 5:ssä (HarmonyOS 5/6). Yhdistämisen jälkeen kello lähettää itse – ilman puhelinsovellusta.",
            "guide.h.s1" to "Avaa kellossa AppGallery, hae ”Pumpfoil” ja asenna sovellus. Salli sijainti ja kehon anturit.",
            "guide.h.s2" to "Avaa Pumpfoil, pyyhkäise ylös asetuksiin ja napauta ›pumpfoil.org‹ – kello näyttää koodin. Syötä se kohdassa ",
            "guide.h.s3" to "Napauta START. Pidä STOP ja Tauko painettuna 2 sekuntia, napauta Hylkää kahdesti.",
            "guide.h.s4" to "Pysäytyksen jälkeen kello lähettää itse heti, kun sillä on internet (Wi-Fi tai yhdistetyn puhelimen kautta). Aloitusnäytössä lukee silloin ”All sent”.",
            "guide.preview" to "Näin se näyttää kellossa:",
