            "guide.settings.title" to "Kellosi asetukset",
            "guide.settings.intro" to "Kun kello on yhdistetty, löydät kullekin kaksi säädintä kohdasta ",
            "guide.settings.intro2" to ". Ne vaikuttavat itse kelloon — se noutaa ne, kun avaat sovelluksen siellä seuraavan kerran, päivitystä ei tarvita. Jos akunkesto on sinulle tärkeä, nämä ovat ne vivut.",
            "guide.settings.recordTitle" to "Tallennustila (kaikki kellot):",
            "guide.settings.record" to "25 Hz, 10 Hz tai pelkkä GPS. 10 Hz säästää akkua eikä maksa juuri mitään — ajoimme molemmat taajuudet samojen sessioiden läpi: pumppauslaskentasi osuu puolen prosentin sisään, ja se mitkä osat lasketaan foilaukseksi on 99,9 % identtinen.",
            "guide.settings.gnssTitle" to "Satelliittijärjestelmät (vain Garmin):",
            "guide.settings.gnss" to "Oletuksena paras mihin kellosi pystyy — kaikki järjestelmät kahdella taajuuskaistalla. Se löytää sijaintisi nopeimmin ja pitää siitä parhaiten kiinni, mutta se maksaa oikeasti akkua. «Ilman toista taajuuskaistaa» säilyttää kaikki järjestelmät ja luopuu vain kalliista lisäkaistasta: eniten säästöä, vähiten menetystä.",
            "guide.settings.gpsWarn" to "Pelkkä GPS säästää eniten, mutta heittää pumppauslaskennan, kadenssin ja liukuvaiheet kokonaan menemään — juuri ne luvut, joita varten tämä sovellus on olemassa. Valitse se vain, jos kellosi ei muuten kestä session läpi.",
            "guide.settings.zepp" to "Amazfitissa tallennustilalla ei ole vielä vaikutusta — kello tallentaa omalla taajuudellaan. Kielen, taukonäkymän ja omat asettelut se sen sijaan ottaa täältä.",
            "watches.title" to "Tuetut kellot",
            "watches.intro" to "Mikä kello tuottaa mitäkin dataa — sinä päätät. Haluamme pitkällä tähtäimellä liittää kaikki yleiset urheilukellot.",
            "watches.colDevice" to "Kello",
            "watches.colGps" to "GPS · matka · nopeus",
            "watches.colHr" to "Syke",
            "watches.colPump" to "Pumps ja liukuvaiheet",
            "watches.colStatus" to "Tila",
            "watches.foot" to "Pumps ja liukuvaiheet tarvitsevat raa'an kiihtyvyyden (≥25 Hz) suoraan kellosta. GPS-tilastoja voi monella merkillä analysoida myös FIT-/datantuonnilla.",
            "watches.legYes" to "täysin tuettu",
            "watches.legPartial" to "rajoitettu",
            "watches.legNo" to "ei saatavilla",
            "watches.linkAccount" to "Tilin linkitys saatavilla",
            "watches.linkViaSuunto" to "Mi Fitness → Suunto",
            "watches.nGarmin" to "Vanhemmat mallit ilman raakakiihtyvyyttä: GPS-tilastot analysoidaan silti.",
            "watches.nApple" to "Raakakiihtyvyys Core Motionin kautta.",
            "watches.nWear" to "Toimii kaikissa Wear OS 3+ -kelloissa — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Sensoripääsy mallista riippuen.",
            "watches.nHuaweiW5" to "Lähettää itse, kun se on yhdistetty koodilla, ilman puhelinsovellusta. Uutena AppGalleryssä.",
            "watches.nHuawei" to "Työn alla: tallennus kellossa, siirto Pumpfoil-sovelluksella Android-puhelimeen. Mitä tietoja kellot antavat, on vielä testattava.",
            "watches.nPolar" to "Linkitä tili → tuo harjoitukset (GPS + HR). Pump-tunnistukseen tarvittavaa korkeataajuista kiihtyvyysvirtaa API-vienti ei toimita (vain erillisen BLE-sensorin kautta).",
            "watches.nSuunto" to "Linkitä tili → tuo harjoitukset (GPS + HR). FIT-vienti ei (vielä) sisällä pump-tunnistukseen tarvittavaa korkeataajuista kiihtyvyysvirtaa.",
            "watches.nXiaomi" to "Ei sovellusta kellossa (Xiaomi ei salli kolmannen osapuolen sovelluksia). Mi Fitness kuitenkin lähettää harjoituksesi virallisesti Suunto-sovellukseen — yhdistä Suunto, niin ne tulevat tänne. Ohjeet kohdassa ”Yhdistetyt tilit”.",
            "watches.nFitbit" to "Kolmannen osapuolen sovellukset lopetettiin.",
            "watches.nStrava" to "Tuonti olisi teknisesti mahdollista, mutta API ei anna korkeataajuista raakakiihtyvyyttä (siis ei pump-tunnistusta) ja on maksumuurin + API-ehtojen takana, jotka eivät sovi avoimeen projektiin — siksi tietoisesti integroimatta.",
            "watches.subStrava" to "aktiviteettiportaali",
