            "settings.garmin.help2" to "Watersport en kiteboarden komen automatisch binnen. Sneeuwprofielen (bijvoorbeeld skiën) en ‘Overig’ verschijnen hieronder ter keuze zodra de eerste activiteit ermee binnen is – zet ze aan als je ze voor snowkiten of landkiten gebruikt.",
            "settings.garmin.help3" to "Opnames met onze Pumpfoil-app op het horloge komen zoals altijd direct binnen en worden niet dubbel geïmporteerd. Alleen zij tellen pumps – Garmin levert geen ruwe versnellingsmeterdata.",
