            "team.alleMeine" to "Al mijn teams",
            "sessions.uploadReplaceAsk" to "Deze rit staat er al (sessie #{id}), maar het bestand is anders. De oude sessie verwijderen en vervangen door dit bestand?\n\nAlleen inkorten kan ook zonder nieuw bestand: via „{trim}” in de sessie.",
            "team.regeln.haftung.titel" to "Aansprakelijkheid",
            "team.regeln.haftung.text" to "Events worden door de teams zelf georganiseerd. pumpfoil.org heeft geen invloed op events of op toezeggingen die daarin worden gedaan, financieel of anderszins, en aanvaardt daarvoor geen verantwoordelijkheid. De gang naar de rechter is uitgesloten. Betalingen en alle andere afspraken regelen organisatoren en deelnemers onafhankelijk van pumpfoil.org.\nEvenmin is pumpfoil.org verantwoordelijk voor de juistheid van gemeten waarden en gegevens of voor eventuele manipulatie ervan. Getoond wordt wat de openbare broncode op GitHub uit de geüploade gegevens berekent; verdere toezeggingen zijn er niet.",
