            "guide.a.s2a" to "Je kunt meteen zonder account opnemen (‘Later verbinden') en de sessie later uploaden. Om te koppelen: in de watch-app ‘Verbinden' → ‘Pairing-code aanmaken' — de getoonde code hier in de tab",
