            "guide.a.s3" to "direct op het horloge swipebare pagina's (configureerbaar in de tab ‘Gegevensvelden'). Stopknop aan het begin en einde van de pagina's.",
            "guide.a.s4Title" to "4. Opnemen:",
            "guide.a.s4" to "App openen → start → foilen → stop. Opname werkt ook offline; sync gebeurt automatisch zodra je online bent.",
