            "guide.w.s1Note" to "De Play Store op je telefoon installeert de telefoon-app — de horloge-app installeer je apart, op het horloge zelf.",
            "guide.w.s2Title" to "2. Verbinden — optioneel:",
            "guide.w.s2a" to "zoals bij Apple Watch — opnemen zonder account kan, later verbinden; of in de horloge-app ‘Verbinden' → ‘Pairing-code aanmaken' en de code hier in de tab",
            "guide.w.s2b" to "invoeren.",
            "guide.w.s3Title" to "3. Gegevensvelden:",
            "guide.w.s3" to "swipebare pagina's, configureerbaar in de tab ‘Gegevensvelden'.",
            "guide.w.s4Title" to "4. Opnemen:",
            "guide.w.s4" to "App openen → start → foilen → stop. Offline opname + automatische sync.",
            "guide.amazfitSub" to "Onze recorder draait op Amazfit-horloges met Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 e.a.).",
            "guide.z.store" to "Installeer de Zepp-app en zoek Pumpfoil in de ingebouwde App Store:",
            "guide.z.s1" to "Installeer de Zepp-app (hierboven) en koppel je Amazfit daarin zoals gebruikelijk.",
            "guide.z.s2" to "In de Zepp-app: Profiel → je Amazfit → App Store → zoek „Pumpfoil“ → Installeren.",
            "guide.z.s3" to "Open Pumpfoil op het horloge, veeg naar ›Verbinden‹ voor een code en voer die in onder ",
            "guide.z.s4" to "Druk op START om op te nemen. Gps en hartslag worden automatisch via wifi/telefoon geüpload.",
            "guide.huaweiSub" to "Onze recorder draait op de HUAWEI WATCH 5 (HarmonyOS 5/6). Na het koppelen uploadt het horloge zelf – zonder telefoon-app.",
            "guide.h.s1" to "Open op het horloge AppGallery, zoek „Pumpfoil” en installeer de app. Sta locatie en lichaamssensoren toe.",
            "guide.h.s2" to "Open Pumpfoil, veeg omhoog naar de instellingen en tik op ›pumpfoil.org‹ – het horloge toont een code. Voer die in onder ",
            "guide.h.s3" to "Tik op START. Houd STOP en Pauze 2 seconden vast, tik twee keer op Verwerpen.",
            "guide.h.s4" to "Na het stoppen uploadt het horloge zelf zodra het internet heeft (wifi of via de gekoppelde telefoon). Het startscherm toont dan „All sent”.",
            "guide.preview" to "Zo ziet het eruit op het horloge:",
