            "guide.settings.title" to "Instellingen voor je horloge",
            "guide.settings.intro" to "Zodra het horloge gekoppeld is, vind je voor elk twee instellingen onder ",
            "guide.settings.intro2" to ". Ze werken op het horloge zelf — het pikt ze op zodra je de app daar de volgende keer opent, geen update nodig. Als batterijduur voor jou telt, zijn dit de knoppen.",
            "guide.settings.recordTitle" to "Opnamemodus (alle horloges):",
            "guide.settings.record" to "25 Hz, 10 Hz of alleen gps. 10 Hz bespaart batterij en kost bijna niets — we hebben beide frequenties over dezelfde sessies laten lopen: je pomptelling blijft binnen een half procent, en welke delen als foilen tellen is voor 99,9 % identiek.",
            "guide.settings.gnssTitle" to "Satellietsystemen (alleen Garmin):",
            "guide.settings.gnss" to "Standaard is het beste wat je horloge kan — alle systemen over twee frequentiebanden. Dat vindt je positie het snelst en houdt hem het best vast, maar het kost echt batterij. «Zonder tweede frequentieband» houdt alle systemen en laat alleen de dure extra band vallen: het meest bespaard voor het minst verloren.",
            "guide.settings.gpsWarn" to "Alleen gps bespaart het meest, maar gooit pomptelling, cadans en glijfases helemaal weg — precies de getallen waarvoor deze app bestaat. Kies dat alleen als je horloge de sessie anders niet volhoudt.",
            "guide.settings.zepp" to "Op Amazfit heeft de opnamemodus nog geen effect — het horloge neemt op met zijn eigen frequentie. Taal, pauzeweergave en eigen lay-outs haalt het wel hiervandaan.",
            "watches.title" to "Ondersteunde horloges",
            "watches.intro" to "Welk horloge levert welke gegevens — jij beslist. We willen op termijn alle gangbare sporthorloges aansluiten.",
            "watches.colDevice" to "Horloge",
            "watches.colGps" to "GPS · afstand · snelheid",
            "watches.colHr" to "Hartslag",
            "watches.colPump" to "Pumps & glijfases",
            "watches.colStatus" to "Status",
            "watches.foot" to "Pumps & glijfases hebben ruwe versnelling (≥25 Hz) direct van het horloge nodig. GPS-stats zijn bij veel merken ook via FIT-/data-import te analyseren.",
            "watches.legYes" to "volledig ondersteund",
            "watches.legPartial" to "beperkt",
            "watches.legNo" to "niet beschikbaar",
            "watches.linkAccount" to "Accountkoppeling beschikbaar",
            "watches.linkViaSuunto" to "via Mi Fitness → Suunto",
            "watches.nGarmin" to "Oudere modellen zonder ruwe accel: GPS-stats worden toch geanalyseerd.",
            "watches.nApple" to "Ruwe versnelling via Core Motion.",
            "watches.nWear" to "Draait op elk Wear OS 3+-horloge — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Sensortoegang afhankelijk van het model.",
            "watches.nHuaweiW5" to "Uploadt zelf na koppelen met een code, zonder telefoon-app. Nieuw in AppGallery.",
            "watches.nHuawei" to "In ontwikkeling: opnemen op het horloge, overdracht via de Pumpfoil-app op een Android-telefoon. Welke gegevens de horloges leveren, moet nog getest worden.",
            "watches.nPolar" to "Account koppelen → trainingen importeren (GPS + HR). De hoogfrequente accel-stream voor de pompdetectie levert de API-export niet (alleen via een aparte BLE-sensor).",
            "watches.nSuunto" to "Account koppelen → trainingen importeren (GPS + HR). De hoogfrequente accel-stream voor de pompdetectie levert de FIT-export (nog) niet.",
            "watches.nXiaomi" to "Geen app op het horloge (Xiaomi laat geen apps van derden toe). Maar Mi Fitness stuurt je trainingen officieel naar de Suunto-app — koppel Suunto en ze komen hier binnen. Uitleg bij ‘Gekoppelde accounts’.",
            "watches.nFitbit" to "Apps van derden zijn stopgezet.",
            "watches.nStrava" to "Import zou technisch kunnen, maar levert via de API geen hoogfrequente ruwe accel (dus geen pompdetectie) en zit achter een paywall + API-voorwaarden die niet bij het open project passen — daarom bewust niet geïntegreerd.",
            "watches.subStrava" to "activiteitenportaal",
