            "sessions.uploadReplaceAsk" to "Tahle jízda už tu je (session #{id}), ale soubor je jiný. Smazat starou session a nahradit ji tímto souborem?\n\nJen zkrátit jde i bez nového souboru: v session přes „{trim}“.",
            "team.regeln.haftung.titel" to "Odpovědnost",
            "team.regeln.haftung.text" to "Akce pořádají samy týmy. pumpfoil.org nemá žádný vliv na akce ani na sliby v nich dané, finanční či jiné, a nepřebírá za ně žádnou odpovědnost. Právní cesta je vyloučena. Platby a všechny další dohody si pořadatelé a účastníci řeší sami, nezávisle na pumpfoil.org.\nStejně tak pumpfoil.org nepřebírá žádnou odpovědnost za to, zda jsou naměřené hodnoty a data správné nebo zda nebyly zmanipulovány. Zobrazuje se to, co z nahraných dat spočítá veřejný zdrojový kód na GitHubu; žádné další záruky neexistují.",
