            "guide.a.s1" to "z App Store.",
            "guide.a.s2Title" to "2. Propojit — volitelné:",
            "guide.a.s2a" to "Můžeš nahrávat hned bez účtu („Propojit později“) a vyjížďku nahrát později. K přiřazení: v aplikaci na hodinkách „Propojit“ → „Vygenerovat párovací kód“ — zobrazený kód zadej zde v záložce",
            "guide.a.s2b" to "zadat.",
            "guide.a.s3Title" to "3. Datová pole:",
            "guide.a.s3" to "přímo na hodinkách listovatelné stránky (konfigurovatelné v záložce „Datová pole“). Tlačítko Stop na začátku a na konci stránek.",
            "guide.a.s4Title" to "4. Nahrávání:",
            "guide.a.s4" to "Otevři aplikaci → Start → foil → Stop. Nahrávání běží i offline; sync proběhne automaticky, jakmile jsi online.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Nainstalovat aplikaci v hodinkách:",
            "guide.w.s1" to "otevři Play Store v hodinkách a najdi „Pumpfoil“.",
            "guide.w.s1Note" to "Play Store v telefonu nainstaluje aplikaci pro telefon — aplikace pro hodinky se instaluje zvlášť, přímo v hodinkách.",
            "guide.w.s2Title" to "2. Propojit — volitelné:",
            "guide.w.s2a" to "jako u Apple Watch — nahrávat bez účtu je možné, propojit později; nebo v aplikaci na hodinkách „Propojit“ → „Vygenerovat párovací kód“ a kód zadej zde v záložce",
            "guide.w.s2b" to "zadat.",
            "guide.w.s3Title" to "3. Datová pole:",
            "guide.w.s3" to "listovatelné stránky, konfigurovatelné v záložce „Datová pole“.",
            "guide.w.s4Title" to "4. Nahrávání:",
            "guide.w.s4" to "Otevři aplikaci → Start → foil → Stop. Offline nahrávání + automatický sync.",
            "guide.amazfitSub" to "Náš rekordér běží na hodinkách Amazfit se Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 a další).",
            "guide.z.store" to "Nainstaluj aplikaci Zepp a najdi Pumpfoil v jejím App Store:",
            "guide.z.s1" to "Nainstaluj aplikaci Zepp (výše) a spáruj své Amazfit jako obvykle.",
            "guide.z.s2" to "V aplikaci Zepp: Profil → tvé Amazfit → App Store → vyhledej „Pumpfoil“ → Instalovat.",
            "guide.z.s3" to "Otevři Pumpfoil na hodinkách, přejeď na ›Připojit‹ pro kód a zadej jej v ",
            "guide.z.s4" to "Stiskni START pro záznam. GPS a tep se nahrají automaticky přes Wi-Fi/telefon.",
            "guide.huaweiSub" to "Náš záznamník běží na HUAWEI WATCH 5 (HarmonyOS 5/6). Po propojení hodinky nahrávají samy – bez aplikace v telefonu.",
            "guide.h.s1" to "Na hodinkách otevři AppGallery, vyhledej „Pumpfoil“ a nainstaluj aplikaci. Povol polohu a tělesné senzory.",
            "guide.h.s2" to "Otevři Pumpfoil, přejeď nahoru do nastavení a klepni na ›pumpfoil.org‹ – hodinky ukážou kód. Zadej ho v ",
            "guide.h.s3" to "Klepni na START. STOP a Pauzu drž 2 sekundy, Zahodit klepni dvakrát.",
            "guide.h.s4" to "Po zastavení hodinky nahrají samy, jakmile mají internet (Wi-Fi nebo přes spárovaný telefon). Na úvodní obrazovce se pak ukáže „All sent“.",
            "guide.preview" to "Takhle to vypadá na hodinkách:",
            "guide.previewVer" to "Takhle to vypadá na hodinkách (v1.0.24):",
