            "guide.settings.title" to "Nastavení pro tvoje hodinky",
            "guide.settings.intro" to "Jakmile jsou hodinky připojené, najdeš pro každé dvě nastavení pod ",
            "guide.settings.intro2" to ". Působí přímo na hodinky — převezmou je, až tam příště otevřeš aplikaci, aktualizace není potřeba. Pokud ti jde o výdrž, tohle jsou ty páky.",
            "guide.settings.recordTitle" to "Režim nahrávání (všechny hodinky):",
            "guide.settings.record" to "25 Hz, 10 Hz nebo jen GPS. 10 Hz šetří baterii a nestojí skoro nic — obě frekvence jsme prohnali stejnými vyjížďkami: počet pumpnutí sedí do půl procenta a to, které části se počítají jako foiling, je z 99,9 % totožné.",
            "guide.settings.gnssTitle" to "Satelitní systémy (jen Garmin):",
            "guide.settings.gnss" to "Ve výchozím stavu je to to nejlepší, co tvoje hodinky umí — všechny systémy přes dvě frekvenční pásma. To najde pozici nejrychleji a nejlépe ji drží, ale stojí to opravdu baterii. „Bez druhého frekvenčního pásma“ ponechá všechny systémy a vypustí jen to drahé pásmo navíc: nejvíc ušetřeno za nejmíň ztraceno.",
            "guide.settings.gpsWarn" to "Jen GPS ušetří nejvíc, ale úplně zahodí počet pumpnutí, kadenci i fáze klouzání — přesně ta čísla, kvůli kterým tahle aplikace existuje. Vol to jen tehdy, když hodinky jinak vyjížďku nevydrží.",
            "guide.settings.zepp" to "Na Amazfitu režim nahrávání zatím nemá vliv — hodinky nahrávají vlastní frekvencí. Jazyk, zobrazení pauzy a vlastní rozvržení si odsud ale berou.",
            "watches.title" to "Podporované hodinky",
            "watches.intro" to "Které hodinky poskytují která data — rozhoduješ ty. Dlouhodobě chceme napojit všechny běžné sportovní hodinky.",
            "watches.colDevice" to "Hodinky",
            "watches.colGps" to "GPS · vzdálenost · rychlost",
            "watches.colHr" to "Tep",
            "watches.colPump" to "Pumpnutí a fáze klouzání",
            "watches.colStatus" to "Stav",
            "watches.foot" to "Pumpnutí a fáze klouzání potřebují surové zrychlení (≥25 Hz) přímo z hodinek. GPS statistiky lze u mnoha značek vyhodnotit i přes FIT/import dat.",
            "watches.legYes" to "plně podporováno",
            "watches.legPartial" to "omezeně",
            "watches.legNo" to "není dostupné",
            "watches.linkAccount" to "Propojení účtu dostupné",
            "watches.linkViaSuunto" to "přes Mi Fitness → Suunto",
            "watches.nGarmin" to "Starší modely bez surového accelu: GPS statistiky se přesto vyhodnotí.",
            "watches.nApple" to "Surové zrychlení přes Core Motion.",
            "watches.nWear" to "Běží na jakýchkoli hodinkách Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Přístup k senzorům podle modelu.",
            "watches.nHuaweiW5" to "Po propojení kódem nahrává sama, bez aplikace v telefonu. Nově v AppGallery.",
            "watches.nHuawei" to "V přípravě: záznam na hodinkách, přenos přes aplikaci Pumpfoil v telefonu s Androidem. Jaká data hodinky dodají, je ještě potřeba otestovat.",
            "watches.nPolar" to "Propoj účet → importuj tréninky (GPS + tep). Vysokofrekvenční accel stream pro rozpoznání pumpnutí API export neposkytuje (jen přes samostatný BLE senzor).",
            "watches.nSuunto" to "Propoj účet → importuj tréninky (GPS + tep). Vysokofrekvenční accel stream pro rozpoznání pumpnutí FIT export (zatím) neposkytuje.",
            "watches.nXiaomi" to "Žádná aplikace v hodinkách (Xiaomi cizí aplikace nepovoluje). Mi Fitness ale oficiálně posílá tvoje tréninky do aplikace Suunto — propoj Suunto a dorazí k nám. Návod v „Propojené účty“.",
            "watches.nFitbit" to "Aplikace třetích stran byly ukončeny.",
            "watches.nStrava" to "Import by byl technicky proveditelný, ale přes API neposkytuje vysokofrekvenční surový accel (tedy žádné rozpoznání pumpnutí) a je za paywallem + API podmínkami, které se k otevřenému projektu nehodí — proto záměrně neintegrováno.",
