            "settings.garmin.help1" to "Tylko aktywności od momentu połączenia, starszych nie pobieramy.",
            "settings.garmin.help2" to "Sporty wodne i kiteboarding przychodzą automatycznie. Profile śnieżne (np. narciarstwo) i „Inne” pojawią się poniżej do wyboru, gdy przyjdzie pierwsza aktywność z nimi – włącz je, jeśli używasz ich do snowkitingu lub landkitingu.",
            "settings.garmin.help3" to "Nagrania naszą aplikacją Pumpfoil na zegarku nadal przychodzą bezpośrednio i nie są importowane podwójnie. Tylko one liczą pompy – Garmin nie dostarcza surowych danych z akcelerometru.",
