            "sessions.uploadReplaceAsk" to "Ta sesja już tu jest (sesja #{id}), ale plik jest inny. Usunąć starą sesję i zastąpić ją tym plikiem?\n\nSamo przycięcie nie wymaga nowego pliku: użyj „{trim}” w sesji.",
            "team.regeln.haftung.titel" to "Odpowiedzialność",
            "team.regeln.haftung.text" to "Wydarzenia organizują same drużyny. pumpfoil.org nie ma żadnego wpływu na wydarzenia ani na składane w nich obietnice, finansowe lub inne, i nie ponosi za nie odpowiedzialności. Droga sądowa jest wykluczona. Płatności i wszelkie inne ustalenia organizatorzy i uczestnicy załatwiają między sobą, niezależnie od pumpfoil.org.\nTak samo pumpfoil.org nie ponosi odpowiedzialności za to, czy zmierzone wartości i dane są poprawne lub czy nie zostały zmanipulowane. Wyświetlane jest to, co publiczny kod źródłowy na GitHubie oblicza z przesłanych danych; innych obietnic nie ma.",
