            "guide.a.s1Title" to "1. Zainstaluj aplikację:",
            "guide.a.s1" to "z App Store.",
            "guide.a.s2Title" to "2. Połączenie — opcjonalnie:",
            "guide.a.s2a" to "Możesz nagrywać od razu, bez konta („Połącz później”), i wysłać sesję dopiero potem. Aby ją powiązać: w aplikacji na zegarku „Połącz” → „Wygeneruj kod parowania” — pokazany kod wpisz tutaj w zakładce",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Pola danych:",
            "guide.a.s3" to "przewijane strony wprost na zegarku (konfigurowalne w zakładce „Pola danych”). Przycisk stop na początku i na końcu stron.",
            "guide.a.s4Title" to "4. Nagrywanie:",
            "guide.a.s4" to "otwórz aplikację → Start → jedź na foilu → Stop. Nagrywanie działa też offline; synchronizacja odbywa się automatycznie po powrocie do sieci.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Zainstaluj aplikację na zegarku:",
            "guide.w.s1" to "otwórz Sklep Play na zegarku i wyszukaj „Pumpfoil”.",
            "guide.w.s1Note" to "Sklep Play w telefonie instaluje aplikację na telefon — aplikacja na zegarek to osobna instalacja, na samym zegarku.",
            "guide.w.s2Title" to "2. Połączenie — opcjonalnie:",
            "guide.w.s2a" to "tak jak przy Apple Watchu — nagrywanie bez konta jest możliwe, połączysz się później; albo w aplikacji na zegarku „Połącz” → „Wygeneruj kod parowania” i wpisz kod tutaj w zakładce",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Pola danych:",
            "guide.w.s3" to "przewijane strony, konfigurowalne w zakładce „Pola danych”.",
            "guide.w.s4Title" to "4. Nagrywanie:",
            "guide.w.s4" to "otwórz aplikację → Start → jedź na foilu → Stop. Nagrywanie offline + automatyczna synchronizacja.",
            "guide.amazfitSub" to "Nasz rejestrator działa na zegarkach Amazfit z Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 i inne).",
            "guide.z.store" to "Zainstaluj aplikację Zepp, a potem znajdź Pumpfoil w jej wbudowanym App Store:",
            "guide.z.s1" to "Zainstaluj aplikację Zepp (powyżej) i sparuj z nią swój Amazfit jak zwykle.",
            "guide.z.s2" to "W aplikacji Zepp: Profil → Twój Amazfit → App Store → wyszukaj „Pumpfoil” → Instaluj.",
            "guide.z.s3" to "Otwórz Pumpfoil na zegarku, przesuń do ›Połącz‹ po kod, a potem wpisz go w ",
            "guide.z.s4" to "Naciśnij START, aby nagrywać. GPS i tętno wysyłają się automatycznie przez Wi-Fi albo telefon.",
            "guide.huaweiSub" to "Nasz rejestrator działa na HUAWEI WATCH 5 (HarmonyOS 5/6). Po połączeniu zegarek sam wysyła dane – bez aplikacji w telefonie.",
            "guide.h.s1" to "Na zegarku otwórz AppGallery, wyszukaj „Pumpfoil” i zainstaluj aplikację. Zezwól na lokalizację i czujniki ciała.",
            "guide.h.s2" to "Otwórz Pumpfoil, przesuń w górę do ustawień i stuknij ›pumpfoil.org‹ – zegarek pokaże kod. Wpisz go w ",
