            "guide.a.s2Title" to "2. Conectar — opcional:",
            "guide.a.s2a" to "Você pode gravar imediatamente sem conta (“Conectar depois”) e enviar a sessão em seguida. Para vinculá-la: no app do relógio “Conectar” → “Gerar código de pareamento” — digite aqui o código exibido na aba",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Campos de dados:",
            "guide.a.s3" to "páginas deslizáveis direto no relógio (configuráveis na aba “Campos de dados”). Botão de parar no início e no fim das páginas.",
            "guide.a.s4Title" to "4. Gravar:",
            "guide.a.s4" to "abra o app → Iniciar → foile → Parar. A gravação também funciona offline; a sincronização acontece automaticamente ao ficar online.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
