            "guide.w.s1Note" to "A Play Store do celular instala o app do celular — o app do relógio é uma instalação separada, no próprio relógio.",
            "guide.w.s2Title" to "2. Conectar — opcional:",
            "guide.w.s2a" to "como no Apple Watch — dá para gravar sem conta e conectar depois; ou no app do relógio “Conectar” → “Gerar código de pareamento” e digite aqui o código na aba",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Campos de dados:",
            "guide.w.s3" to "páginas deslizáveis, configuráveis na aba “Campos de dados”.",
            "guide.w.s4Title" to "4. Gravar:",
            "guide.w.s4" to "abra o app → Iniciar → foile → Parar. Gravação offline + sincronização automática.",
            "guide.amazfitSub" to "Nosso gravador roda em relógios Amazfit com Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 e outros).",
            "guide.z.store" to "Baixe o app Zepp e, então, encontre o Pumpfoil na App Store integrada dele:",
            "guide.z.s1" to "Instale o app Zepp (acima) e pareie seu Amazfit nele como de costume.",
            "guide.z.s2" to "No app Zepp: Perfil → seu Amazfit → App Store → busque “Pumpfoil” → Instalar.",
            "guide.z.s3" to "Abra o Pumpfoil no relógio, deslize até ›Conectar‹ para pegar um código e digite-o em ",
            "guide.z.s4" to "Aperte START para gravar. GPS e frequência cardíaca sobem automaticamente por Wi-Fi ou pelo seu celular.",
            "guide.huaweiSub" to "Nosso gravador roda no HUAWEI WATCH 5 (HarmonyOS 5/6). Depois de vinculado, o relógio envia sozinho – sem app no celular.",
            "guide.h.s1" to "No relógio, abra a AppGallery, procure “Pumpfoil” e instale o app. Permita localização e sensores corporais.",
            "guide.h.s2" to "Abra o Pumpfoil, deslize para cima até as configurações e toque em ›pumpfoil.org‹ – o relógio mostra um código. Digite-o em ",
            "guide.h.s3" to "Toque em START. Segure STOP e Pausa por 2 segundos, toque em Descartar duas vezes.",
            "guide.h.s4" to "Depois de parar, o relógio envia sozinho assim que tiver internet (Wi-Fi ou pelo celular pareado). A tela inicial mostra então “All sent”.",
