            "guide.settings.intro" to "Assim que o relógio estiver conectado, você encontra dois controles para cada um em ",
            "guide.settings.intro2" to ". Eles agem no próprio relógio — ele os pega da próxima vez que você abrir o app lá, sem precisar atualizar. Se a autonomia importa para você, são estas as alavancas.",
            "guide.settings.recordTitle" to "Modo de gravação (todos os relógios):",
            "guide.settings.record" to "25 Hz, 10 Hz ou só GPS. 10 Hz economiza bateria e quase não custa nada — rodamos as duas frequências nas mesmas sessões: sua contagem de bombeios fica dentro de meio por cento, e quais trechos contam como foiling é 99,9 % idêntico.",
            "guide.settings.gnssTitle" to "Sistemas de satélites (só Garmin):",
            "guide.settings.gnss" to "Por padrão é o melhor que seu relógio consegue — todos os sistemas em duas bandas de frequência. Isso encontra sua posição mais rápido e a segura melhor, mas custa bateria de verdade. «Sem segunda banda de frequência» mantém todos os sistemas e abre mão só da banda extra cara: o máximo de economia com a menor perda.",
            "guide.settings.gpsWarn" to "Só GPS é o que mais economiza, mas joga fora por completo a contagem de bombeios, a cadência e as fases de planeio — justamente os números pelos quais este app existe. Escolha isso só se o relógio não aguentar a sessão de outro jeito.",
            "guide.settings.zepp" to "No Amazfit o modo de gravação ainda não tem efeito — o relógio grava na frequência dele mesmo. O idioma, a visualização de pausa e os layouts próprios ele pega daqui.",
            "watches.title" to "Relógios suportados",
            "watches.intro" to "Qual relógio dá quais dados — você decide. No longo prazo queremos dar suporte a todos os relógios esportivos comuns.",
