            "watches.colStatus" to "Status",
            "watches.foot" to "Pumps e fases de planeio precisam de aceleração bruta (≥25 Hz) direto do relógio. As estatísticas de GPS podem ser analisadas via importação FIT/dados para muitas marcas.",
            "watches.legYes" to "totalmente suportado",
