            "watches.nWear" to "Roda em qualquer relógio Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "O acesso ao sensor depende do modelo.",
