            "guide.a.s1Title" to "1. Instala a app:",
            "guide.a.s1" to "na App Store.",
            "guide.a.s2Title" to "2. Ligar — opcional:",
            "guide.a.s2a" to "Podes gravar imediatamente sem conta (“Ligar depois”) e enviar a sessão a seguir. Para a associares: na app do relógio “Ligar” → “Gerar código de emparelhamento” — escreve aqui o código apresentado no separador",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Campos de dados:",
            "guide.a.s3" to "páginas deslizáveis direto no relógio (configuráveis na aba “Campos de dados”). Botão de parar no início e no fim das páginas.",
            "guide.a.s4Title" to "4. Gravar:",
            "guide.a.s4" to "abre a app → Iniciar → foila → Parar. A gravação também funciona offline; a sincronização acontece automaticamente ao ficares online.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Instala a app no relógio:",
            "guide.w.s1" to "abre a Play Store no relógio e procura “Pumpfoil”.",
            "guide.w.s1Note" to "A Play Store do telemóvel instala a app do telemóvel — a app do relógio é uma instalação separada, no próprio relógio.",
            "guide.w.s2Title" to "2. Ligar — opcional:",
            "guide.w.s2a" to "como no Apple Watch — dá para gravar sem conta e ligar depois; ou na app do relógio “Ligar” → “Gerar código de emparelhamento” e escreve aqui o código no separador",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Campos de dados:",
            "guide.w.s3" to "páginas deslizáveis, configuráveis na aba “Campos de dados”.",
            "guide.w.s4Title" to "4. Gravar:",
            "guide.w.s4" to "abre a app → Iniciar → foila → Parar. Gravação offline + sincronização automática.",
            "guide.amazfitSub" to "Nosso gravador roda em relógios Amazfit com Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 e outros).",
            "guide.z.store" to "Transfere a app Zepp e, depois, encontra o Pumpfoil na App Store integrada dela:",
            "guide.z.s1" to "Instala a app Zepp (acima) e emparelha aí o teu Amazfit como de costume.",
            "guide.z.s2" to "Na app Zepp: Perfil → o teu Amazfit → App Store → procura “Pumpfoil” → Instalar.",
            "guide.z.s3" to "Abre o Pumpfoil no relógio, desliza até ›Ligar‹ para obteres um código e escreve-o em ",
            "guide.z.s4" to "Carrega em START para gravar. GPS e frequência cardíaca sobem automaticamente por Wi-Fi ou pelo teu telemóvel.",
            "guide.huaweiSub" to "O nosso gravador funciona no HUAWEI WATCH 5 (HarmonyOS 5/6). Depois de associado, o relógio envia sozinho – sem app no telemóvel.",
            "guide.h.s1" to "No relógio, abre a AppGallery, procura “Pumpfoil” e instala a app. Permite a localização e os sensores corporais.",
            "guide.h.s2" to "Abre o Pumpfoil, desliza para cima até às definições e toca em ›pumpfoil.org‹ – o relógio mostra um código. Introduz-o em ",
            "guide.h.s3" to "Toca em START. Mantém STOP e Pausa durante 2 segundos, toca duas vezes em Descartar.",
            "guide.h.s4" to "Depois de parar, o relógio envia sozinho assim que tiver internet (Wi-Fi ou através do telemóvel emparelhado). O ecrã inicial mostra então “All sent”.",
            "guide.preview" to "Como fica no relógio:",
