            "guide.settings.intro" to "Assim que o relógio estiver ligado, encontras dois controlos para cada um em ",
            "guide.settings.intro2" to ". Agem no próprio relógio — ele vai buscá-los da próxima vez que abrires a app lá, sem precisares de atualizar. Se a autonomia te importa, são estas as alavancas.",
            "guide.settings.recordTitle" to "Modo de gravação (todos os relógios):",
            "guide.settings.record" to "25 Hz, 10 Hz ou só GPS. 10 Hz poupa bateria e quase não custa nada — corremos as duas frequências nas mesmas sessões: a tua contagem de bombeios fica dentro de meio por cento, e que troços contam como foiling é 99,9 % idêntico.",
            "guide.settings.gnssTitle" to "Sistemas de satélites (só Garmin):",
            "guide.settings.gnss" to "Por predefinição é o melhor que o teu relógio consegue — todos os sistemas em duas bandas de frequência. Isso encontra a tua posição mais depressa e segura-a melhor, mas custa bateria a sério. «Sem segunda banda de frequência» mantém todos os sistemas e abdica só da banda extra cara: o máximo de poupança com a menor perda.",
            "guide.settings.gpsWarn" to "Só GPS é o que mais poupa, mas deita fora por completo a contagem de bombeios, a cadência e as fases de planeio — precisamente os números pelos quais esta app existe. Escolhe isso só se o relógio não aguentar a sessão de outra maneira.",
            "guide.settings.zepp" to "No Amazfit o modo de gravação ainda não tem efeito — o relógio grava na frequência dele mesmo. O idioma, a visualização de pausa e os layouts próprios ele pega daqui.",
            "watches.title" to "Relógios suportados",
