            "guide.settings.intro2" to "。これらは時計本体に作用し、次に時計でアプリを開いたときに反映されます。アップデートは不要です。電池もちを重視するなら、ここが効きます。",
            "guide.settings.recordTitle" to "記録モード（すべての時計）：",
            "guide.settings.record" to "25 Hz、10 Hz、または GPS のみ。10 Hz はバッテリーを節約でき、失うものはほとんどありません — 同じセッションで両方のレートを走らせて比べました：ポンプ数の差は 0.5 % 以内、どの区間をフォイリングと数えるかは 99.9 % 一致します。",
            "guide.settings.gnssTitle" to "衛星システム（Garmin のみ）：",
            "guide.settings.gnss" to "既定はお使いの時計にできる最良の設定です — すべてのシステムを 2 つの周波数帯で使います。位置を最も速く捉え、最もよく保ちますが、バッテリーを実際に消費します。「第 2 周波数帯なし」はすべてのシステムを残し、コストの高い追加帯だけをやめます：失うものが最小で、節約が最大です。",
            "guide.settings.gpsWarn" to "GPS のみが最も節約できますが、ポンプ数・ケイデンス・滑走フェーズをまるごと捨ててしまいます — このアプリが存在する理由そのものの数値です。時計がセッションを持ちこたえられない場合にだけ選んでください。",
            "guide.settings.zepp" to "Amazfit では記録モードはまだ効きません — 時計は独自のレートで記録します。言語・一時停止表示・自作レイアウトはここから取得します。",
