            "brett.erkl.was" to "如果滑行时手机固定在板上，它的陀螺仪会测量板子的俯仰和横滚——直接在源头测量，而不是在手腕上。",
            "brett.erkl.wie" to "使用方法：把手机放进防水袋，平放固定在板面上，然后在手机上的 Pumpfoil 应用中开始记录。手表可以同时记录。分析通常会自动识别手机在板上。",
            "brett.erkl.bringt" to "有什么用：你可以看到泵动时板子有多稳，每次泵动俯仰和横滚多大，以及不同水翼、转弯和直线之间是否有差别。每一次这样的记录也有助于改进手表的泵动识别。",
            "brett.erkl.daten" to "你会得到的数据：每次泵动的俯仰和横滚、倾斜、节奏、转弯与直线对比，以及上下起伏（在可靠识别泵动节奏后）——按每段显示，这里汇总所有段并按水翼显示。",
