            "guide.a.s1" to "从 App Store 获取。",
            "guide.a.s2Title" to "2. 连接 —— 可选：",
            "guide.a.s2a" to "你可以不用账号立即记录（“稍后连接”），之后再上传记录。要关联它：在手表应用中“连接” → “生成配对码” —— 在此标签中输入显示的配对码",
