            "guide.a.s3Title" to "3. 数据字段：",
            "guide.a.s3" to "手表上可滑动的页面（在“数据字段”标签中配置）。页面开头和结尾都有停止按钮。",
            "guide.a.s4Title" to "4. 记录：",
            "guide.a.s4" to "打开应用 → 开始 → 水翼滑行 → 停止。记录离线也可用；联网后自动同步。",
            "guide.wearSub" to "Samsung Galaxy Watch、Google Pixel Watch …",
            "guide.w.s1Title" to "1. 在手表上安装应用：",
            "guide.w.s1" to "在手表上打开 Google Play 商店，搜索「Pumpfoil」。",
            "guide.w.s1Note" to "手机上的 Play 商店安装的是手机应用 — 手表应用需要在手表上单独安装。",
            "guide.w.s2Title" to "2. 连接 —— 可选：",
            "guide.w.s2a" to "与 Apple Watch 类似 —— 可不用账号记录，稍后连接；或在手表应用中“连接” → “生成配对码”，并在此标签中输入配对码",
            "guide.w.s2b" to "。",
            "guide.w.s3Title" to "3. 数据字段：",
            "guide.w.s3" to "可滑动的页面，在“数据字段”标签中配置。",
            "guide.w.s4Title" to "4. 记录：",
            "guide.w.s4" to "打开应用 → 开始 → 水翼滑行 → 停止。离线记录 + 自动同步。",
            "guide.amazfitSub" to "我们的记录器可运行在搭载 Zepp OS 的 Amazfit 手表上（Balance、T-Rex 3、Cheetah、Active 2/3 等）。",
            "guide.z.store" to "先安装 Zepp 应用，然后在其内置应用商店中找到 Pumpfoil：",
            "guide.z.s1" to "安装 Zepp 应用（如上），并在其中照常配对你的 Amazfit。",
            "guide.z.s2" to "在 Zepp 应用中：个人资料 → 你的 Amazfit → 应用商店 → 搜索“Pumpfoil” → 安装。",
            "guide.z.s3" to "在手表上打开 Pumpfoil，滑动到 ›连接‹ 获取配对码，然后在以下位置输入 ",
            "guide.z.s4" to "按 START 开始记录。GPS 和心率会通过 Wi-Fi 或你的手机自动上传。",
            "guide.huaweiSub" to "我们的记录器可在 HUAWEI WATCH 5（HarmonyOS 5/6）上运行。绑定后手表会自行上传，无需手机应用。",
            "guide.h.s1" to "在手表上打开 AppGallery，搜索“Pumpfoil”并安装。允许位置和身体传感器权限。",
            "guide.h.s2" to "打开 Pumpfoil，向上滑到设置，点击 ›pumpfoil.org‹，手表会显示一个代码。在此输入：",
            "guide.h.s3" to "点击 START。STOP 和暂停需按住 2 秒，丢弃需点两次。",
            "guide.h.s4" to "停止后，手表一联网（Wi-Fi 或通过已配对的手机）就会自行上传。完成后开始界面显示“All sent”。",
