            "guide.settings.title" to "你的手表设置",
            "guide.settings.intro" to "手表连接后，你可以在以下位置为每块手表找到两项设置：",
            "guide.settings.intro2" to "。它们作用于手表本身——下次你在手表上打开应用时就会取用，无需更新。如果你在意续航，这两项就是关键。",
            "guide.settings.recordTitle" to "记录模式（所有手表）：",
            "guide.settings.record" to "25 Hz、10 Hz 或仅 GPS。10 Hz 省电，代价几乎为零——我们用同一批会话跑过两种频率：泵动计数的差异在千分之五以内，哪些片段算作 foiling 的判定有 99.9 % 一致。",
            "guide.settings.gnssTitle" to "卫星系统（仅 Garmin）：",
            "guide.settings.gnss" to "默认是你的手表能做到的最好设置——所有系统、双频段。这样定位最快、保持得最好，但确实费电。「不使用第二频段」保留全部系统，只放弃昂贵的额外频段：省得最多，失得最少。",
            "guide.settings.gpsWarn" to "仅 GPS 最省电，但会彻底丢掉泵动计数、频率和滑行阶段——恰恰是这个应用存在的意义所在。只有当手表否则撑不完整场时才选它。",
            "guide.settings.zepp" to "在 Amazfit 上，记录模式暂时不起作用——手表按自己的频率记录。语言、暂停界面和自定义布局它确实从这里获取。",
            "watches.title" to "支持的手表",
            "watches.intro" to "哪块手表提供哪些数据 —— 由你决定。长远来看我们希望支持所有常见的运动手表。",
