            "watches.nPolar" to "关联你的账号 → 导入训练（GPS + 心率）。API 导出不包含泵动识别所需的高频原始加速度流（只能通过单独的 BLE 传感器获取）。",
            "watches.nSuunto" to "关联你的账号 → 导入训练（GPS + 心率）。FIT 导出（暂时）不包含泵动识别所需的高频原始加速度流。",
            "watches.nXiaomi" to "手表上无法安装应用（小米不允许第三方应用）。但小米运动健康会官方推送你的运动到 Suunto 应用——连接 Suunto，数据就会到达这里。说明见“已连接账号”。",
