            "brett.erkl.was" to "Если телефон закреплён на доске во время сессии, его гироскоп измеряет, как доска клюёт и кренится — прямо у источника, а не на запястье.",
            "brett.erkl.wie" to "Как это сделать: положи телефон в водонепроницаемый чехол, закрепи его плашмя на деке и начни запись в приложении Pumpfoil на телефоне. Часы могут записывать одновременно. Что телефон был на доске, анализ обычно определяет сам.",
            "brett.erkl.bringt" to "Что это даёт: ты видишь, насколько ровно идёт доска при пампинге, насколько сильно она клюёт и кренится на каждом пампе и отличается ли это между фойлами, поворотами и прямыми. Каждая такая запись также помогает улучшить распознавание пампов для часов.",
