            "guide.appleSub" to "watchOS 9+",
            "guide.a.s1Title" to "1. Установите приложение:",
            "guide.a.s1" to "из App Store.",
            "guide.a.s2Title" to "2. Подключение — опционально:",
            "guide.a.s2a" to "Можно записывать сразу без аккаунта («Подключить позже») и загрузить сессию потом. Чтобы привязать её: в приложении на часах «Подключение» → «Сгенерировать код сопряжения» — введите показанный код здесь во вкладке",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Поля данных:",
            "guide.a.s3" to "листаемые страницы прямо на часах (настраиваются во вкладке «Поля данных»). Кнопка стоп в начале и в конце страниц.",
            "guide.a.s4Title" to "4. Запись:",
            "guide.a.s4" to "откройте приложение → Старт → фойлите → Стоп. Запись работает и офлайн; синхронизация происходит автоматически при появлении сети.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Установите приложение на часы:",
            "guide.w.s1" to "откройте Play Store на часах и найдите «Pumpfoil».",
            "guide.w.s1Note" to "Play Store на телефоне устанавливает приложение для телефона — приложение для часов устанавливается отдельно, на самих часах.",
            "guide.w.s2Title" to "2. Подключение — опционально:",
            "guide.w.s2a" to "как Apple Watch — запись без аккаунта возможна, подключить можно позже; или в приложении на часах «Подключение» → «Сгенерировать код сопряжения» и введите код здесь во вкладке",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Поля данных:",
            "guide.w.s3" to "листаемые страницы, настраиваются во вкладке «Поля данных».",
            "guide.w.s4Title" to "4. Запись:",
            "guide.w.s4" to "откройте приложение → Старт → фойлите → Стоп. Офлайн-запись + автоматическая синхронизация.",
            "guide.amazfitSub" to "Наш рекордер работает на часах Amazfit с Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 и другие).",
            "guide.z.store" to "Установите приложение Zepp, затем найдите Pumpfoil в его встроенном магазине приложений:",
            "guide.z.s1" to "Установите приложение Zepp (выше) и как обычно сопрягите в нём ваш Amazfit.",
            "guide.z.s2" to "В приложении Zepp: Профиль → ваш Amazfit → App Store → поиск «Pumpfoil» → Установить.",
            "guide.z.s3" to "Откройте Pumpfoil на часах, смахните к ›Подключение‹ для кода, затем введите его в разделе ",
            "guide.z.s4" to "Нажмите START для записи. GPS и пульс загружаются автоматически по Wi-Fi или через телефон.",
            "guide.huaweiSub" to "Наш рекордер работает на HUAWEI WATCH 5 (HarmonyOS 5/6). После привязки часы сами загружают данные — без приложения на телефоне.",
            "guide.h.s1" to "На часах открой AppGallery, найди «Pumpfoil» и установи приложение. Разреши доступ к геопозиции и датчикам тела.",
            "guide.h.s2" to "Открой Pumpfoil, смахни вверх к настройкам и нажми ›pumpfoil.org‹ — часы покажут код. Введи его в разделе ",
            "guide.h.s3" to "Нажми START. STOP и Паузу удерживай 2 секунды, «Удалить» нажми дважды.",
            "guide.h.s4" to "После остановки часы сами загрузят данные, как только появится интернет (Wi-Fi или через сопряжённый телефон). На стартовом экране появится «All sent».",
            "guide.preview" to "Как это выглядит на часах:",
