            "guide.settings.title" to "Настройки для твоих часов",
            "guide.settings.intro" to "Как только часы подключены, для каждых из них ты найдёшь две настройки в разделе ",
            "guide.settings.intro2" to ". Они действуют на сами часы — те подхватят их при следующем открытии приложения, обновление не нужно. Если для тебя важно время работы, это те самые рычаги.",
            "guide.settings.recordTitle" to "Режим записи (все часы):",
            "guide.settings.record" to "25 Гц, 10 Гц или только GPS. 10 Гц экономит батарею и почти ничего не стоит — мы прогнали обе частоты по одним и тем же сессиям: счётчик помпинга укладывается в полпроцента, а какие участки считаются катанием, совпадает на 99,9 %.",
            "guide.settings.gnssTitle" to "Спутниковые системы (только Garmin):",
            "guide.settings.gnss" to "По умолчанию — лучшее, на что способны твои часы: все системы в двух частотных диапазонах. Так позиция находится быстрее всего и держится лучше всего, но это по-настоящему стоит батареи. «Без второго частотного диапазона» сохраняет все системы и отказывается только от дорогого дополнительного диапазона: максимум экономии при минимуме потерь.",
            "guide.settings.gpsWarn" to "Только GPS экономит больше всего, но полностью выбрасывает счётчик помпинга, каденс и фазы глиссирования — как раз те числа, ради которых существует это приложение. Выбирай это, только если иначе часам не хватит на всю сессию.",
            "guide.settings.zepp" to "На Amazfit режим записи пока не действует — часы записывают со своей частотой. Язык, вид паузы и собственные раскладки они при этом берут отсюда.",
            "watches.title" to "Поддерживаемые часы",
            "watches.intro" to "Какие часы дают какие данные — решаете вы. В долгосрочной перспективе мы хотим поддержать все распространённые спортивные часы.",
