            "watches.colStatus" to "Статус",
            "watches.foot" to "Помпингу и фазам скольжения нужно сырое ускорение (≥25 Hz) прямо с часов. GPS-статистику можно проанализировать через импорт FIT/данных для многих брендов.",
            "watches.legYes" to "полностью поддерживается",
