            "watches.nApple" to "Сырое ускорение через Core Motion.",
            "watches.nWear" to "Работает на любых часах с Wear OS 3+ — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Доступ к датчикам зависит от модели.",
            "watches.nHuaweiW5" to "После привязки по коду загружает данные сама, без приложения на телефоне. Новинка в AppGallery.",
            "watches.nHuawei" to "В работе: запись на часах, передача через приложение Pumpfoil на телефоне с Android. Какие данные дают часы, ещё нужно проверить.",
            "watches.nPolar" to "Привяжите аккаунт → импорт тренировок (GPS + пульс). Экспорт через API не включает высокочастотный поток сырого ускорения, нужный для распознавания помпинга (только через отдельный BLE-датчик).",
