            "watches.nXiaomi" to "Приложения на часах нет (Xiaomi не допускает сторонние). Зато Mi Fitness официально отправляет тренировки в приложение Suunto — подключи Suunto, и они придут к нам. Инструкция в «Связанные аккаунты».",
            "watches.nFitbit" to "Сторонние приложения прекращены.",
