            "settings.garmin.help1" to "Hanya aktivitas sejak ditautkan; yang lebih lama tidak kami ambil.",
            "settings.garmin.help2" to "Olahraga air dan kiteboarding masuk otomatis. Profil salju (misalnya ski) dan «Lainnya» muncul di bawah sebagai pilihan begitu aktivitas pertama dengannya masuk – nyalakan jika kamu memakainya untuk snowkite atau landkite.",
            "settings.garmin.help3" to "Rekaman dengan aplikasi Pumpfoil kami di jam tetap masuk langsung dan tidak diimpor dua kali. Hanya rekaman itu yang menghitung pump – Garmin tidak menyediakan data mentah akselerometer.",
