            "sessions.uploadReplaceAsk" to "Sesi ini sudah ada (sesi #{id}), tetapi filenya berbeda. Hapus sesi lama dan ganti dengan file ini?\n\nUntuk sekadar memotong tidak perlu file baru: gunakan “{trim}” di sesi.",
            "team.regeln.haftung.titel" to "Tanggung jawab",
            "team.regeln.haftung.text" to "Event diselenggarakan oleh tim itu sendiri. pumpfoil.org tidak memiliki pengaruh atas event maupun janji yang dibuat di dalamnya, baik finansial maupun lainnya, dan tidak bertanggung jawab atasnya. Jalur hukum dikecualikan. Pembayaran dan semua kesepakatan lain diatur antara penyelenggara dan peserta, terlepas dari pumpfoil.org.\nBegitu pula, pumpfoil.org tidak bertanggung jawab atas benar tidaknya nilai dan data yang diukur atau apakah data tersebut dimanipulasi. Yang ditampilkan adalah hasil perhitungan kode sumber publik di GitHub dari data yang diunggah; tidak ada janji lain.",
