            "guide.appleSub" to "watchOS 9+",
            "guide.a.s1Title" to "1. Pasang aplikasi:",
            "guide.a.s1" to "dari App Store.",
            "guide.a.s2Title" to "2. Hubungkan — opsional:",
            "guide.a.s2a" to "Kamu bisa langsung merekam tanpa akun (“Hubungkan nanti”) dan mengunggah sesi setelahnya. Untuk menautkannya: di aplikasi jam “Hubungkan” → “Buat kode pairing” — masukkan kode yang ditampilkan di sini di tab",
            "guide.a.s2b" to ".",
            "guide.a.s3Title" to "3. Data field:",
            "guide.a.s3" to "halaman yang bisa digeser langsung di jam (bisa dikonfigurasi di tab “Data field”). Tombol stop di awal dan akhir halaman.",
            "guide.a.s4Title" to "4. Rekam:",
            "guide.a.s4" to "buka aplikasi → Mulai → foiling → Stop. Perekaman juga berfungsi offline; sinkron terjadi otomatis begitu online.",
            "guide.wearSub" to "Samsung Galaxy Watch, Google Pixel Watch …",
            "guide.w.s1Title" to "1. Pasang aplikasi di jam:",
            "guide.w.s1" to "buka Play Store di jam dan cari “Pumpfoil”.",
            "guide.w.s1Note" to "Play Store di ponsel memasang aplikasi ponsel — aplikasi jam dipasang terpisah, di jam itu sendiri.",
            "guide.w.s2Title" to "2. Hubungkan — opsional:",
            "guide.w.s2a" to "seperti Apple Watch — merekam tanpa akun bisa, hubungkan nanti; atau di aplikasi jam “Hubungkan” → “Buat kode pairing” dan masukkan kodenya di sini di tab",
            "guide.w.s2b" to ".",
            "guide.w.s3Title" to "3. Data field:",
            "guide.w.s3" to "halaman yang bisa digeser, bisa dikonfigurasi di tab “Data field”.",
            "guide.w.s4Title" to "4. Rekam:",
            "guide.w.s4" to "buka aplikasi → Mulai → foiling → Stop. Perekaman offline + sinkron otomatis.",
            "guide.amazfitSub" to "Perekam kami berjalan di jam Amazfit dengan Zepp OS (Balance, T-Rex 3, Cheetah, Active 2/3 dan lainnya).",
            "guide.z.store" to "Dapatkan aplikasi Zepp, lalu temukan Pumpfoil di App Store bawaannya:",
            "guide.z.s1" to "Pasang aplikasi Zepp (di atas) dan pasangkan Amazfit-mu di dalamnya seperti biasa.",
            "guide.z.s2" to "Di aplikasi Zepp: Profil → Amazfit-mu → App Store → cari “Pumpfoil” → Pasang.",
            "guide.z.s3" to "Buka Pumpfoil di jam, geser ke ›Hubungkan‹ untuk kode, lalu masukkan di ",
            "guide.z.s4" to "Tekan START untuk merekam. GPS dan detak jantung terunggah otomatis lewat Wi-Fi atau ponselmu.",
            "guide.huaweiSub" to "Perekam kami berjalan di HUAWEI WATCH 5 (HarmonyOS 5/6). Setelah ditautkan, jam mengunggah sendiri – tanpa aplikasi ponsel.",
            "guide.h.s1" to "Di jam, buka AppGallery, cari “Pumpfoil” lalu instal aplikasinya. Izinkan lokasi dan sensor tubuh.",
            "guide.h.s2" to "Buka Pumpfoil, usap ke atas ke pengaturan dan ketuk ›pumpfoil.org‹ – jam menampilkan kode. Masukkan di ",
            "guide.h.s3" to "Ketuk START. Tahan STOP dan Jeda 2 detik, ketuk Buang dua kali.",
            "guide.h.s4" to "Setelah berhenti, jam mengunggah sendiri begitu ada internet (Wi-Fi atau lewat ponsel yang dipasangkan). Layar awal lalu menampilkan “All sent”.",
            "guide.preview" to "Seperti apa tampilannya di jam:",
            "guide.previewVer" to "Seperti apa tampilannya di jam (v1.0.24):",
