            "guide.settings.title" to "Pengaturan untuk jammu",
            "guide.settings.intro" to "Setelah jam terhubung, untuk masing-masing kamu menemukan dua pengaturan di ",
            "guide.settings.intro2" to ". Keduanya berlaku pada jamnya sendiri — jam mengambilnya saat kamu membuka aplikasi di sana berikutnya, tidak perlu pembaruan. Kalau daya tahan baterai penting bagimu, inilah tuasnya.",
            "guide.settings.recordTitle" to "Mode perekaman (semua jam):",
            "guide.settings.record" to "25 Hz, 10 Hz atau hanya GPS. 10 Hz menghemat baterai dan nyaris tidak berbiaya — kami menjalankan kedua laju pada sesi yang sama: hitungan pumping-mu meleset kurang dari setengah persen, dan bagian mana yang dihitung sebagai foiling identik 99,9 %.",
            "guide.settings.gnssTitle" to "Sistem satelit (hanya Garmin):",
            "guide.settings.gnss" to "Bawaannya adalah yang terbaik yang bisa dilakukan jammu — semua sistem di dua pita frekuensi. Itu menemukan posisimu paling cepat dan mempertahankannya paling baik, tapi benar-benar memakan baterai. «Tanpa pita frekuensi kedua» mempertahankan semua sistem dan hanya melepas pita tambahan yang mahal: paling hemat dengan kehilangan paling sedikit.",
            "guide.settings.gpsWarn" to "Hanya GPS paling hemat, tapi membuang hitungan pumping, kadens dan fase meluncur sama sekali — justru angka-angka yang menjadi alasan aplikasi ini ada. Pilih itu hanya kalau jammu tidak akan bertahan sepanjang sesi.",
            "guide.settings.zepp" to "Di Amazfit mode perekaman belum berpengaruh — jam merekam dengan laju sendiri. Bahasa, tampilan jeda dan tata letak sendiri memang diambilnya dari sini.",
            "watches.title" to "Jam yang didukung",
            "watches.intro" to "Jam mana memberi data apa — kamu yang menentukan. Jangka panjang kami ingin mendukung semua jam olahraga umum.",
            "watches.colDevice" to "Jam",
            "watches.colGps" to "GPS · jarak · kecepatan",
            "watches.colHr" to "Detak jantung",
            "watches.colPump" to "Fase pump & glide",
            "watches.colStatus" to "Status",
            "watches.foot" to "Fase pump & glide butuh akselerasi mentah (≥25 Hz) langsung dari jam. Statistik GPS bisa dianalisis via impor FIT/data untuk banyak merek.",
            "watches.legYes" to "didukung penuh",
            "watches.legPartial" to "terbatas",
            "watches.legNo" to "tidak tersedia",
            "watches.linkAccount" to "Penautan akun tersedia",
            "watches.linkViaSuunto" to "lewat Mi Fitness → Suunto",
            "watches.nGarmin" to "Model lama tanpa accel mentah: statistik GPS tetap dianalisis.",
            "watches.nApple" to "Akselerasi mentah via Core Motion.",
            "watches.nWear" to "Berjalan di jam Wear OS 3+ mana pun — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
            "watches.nAmazfit" to "Akses sensor tergantung modelnya.",
            "watches.nHuaweiW5" to "Mengunggah sendiri setelah ditautkan dengan kode, tanpa aplikasi ponsel. Baru di AppGallery.",
            "watches.nHuawei" to "Sedang dikerjakan: merekam di jam, transfer lewat aplikasi Pumpfoil di ponsel Android. Data apa yang diberikan tiap jam masih perlu diuji.",
            "watches.nPolar" to "Tautkan akunmu → impor latihan (GPS + HR). Ekspor API tidak menyertakan aliran accel mentah laju-tinggi yang dibutuhkan untuk deteksi pump (hanya via sensor BLE terpisah).",
            "watches.nSuunto" to "Tautkan akunmu → impor latihan (GPS + HR). Ekspor FIT (belum) menyertakan aliran accel mentah laju-tinggi yang dibutuhkan untuk deteksi pump.",
            "watches.nXiaomi" to "Tidak ada aplikasi di jam (Xiaomi tidak mengizinkan aplikasi pihak ketiga). Tapi Mi Fitness resmi mengirim latihanmu ke aplikasi Suunto — hubungkan Suunto dan latihan masuk ke sini. Panduan di “Akun Terhubung”.",
            "watches.nFitbit" to "Aplikasi pihak ketiga telah dihentikan.",
            "watches.nStrava" to "Impor secara teknis mungkin saja, tapi API tidak menyediakan data mentah akselerometer berfrekuensi tinggi (jadi tanpa deteksi pumping), dan ia berada di balik paywall dengan syarat API yang tidak cocok untuk proyek terbuka — sengaja tidak diintegrasikan.",
            "watches.subStrava" to "portal aktivitas",
