            "brett.erkl.wie" to "Slik gjør du det: legg telefonen i et vanntett etui, fest den flatt på dekket og start opptaket i Pumpfoil-appen på telefonen. Klokka kan ta opp samtidig. At telefonen lå på brettet, oppdager analysen som regel selv.",
            "brett.erkl.bringt" to "Hva du får ut av det: du ser hvor stødig brettet ligger når du pumper, hvor mye det nikker og ruller per pump, og om det er forskjell mellom foiler, svinger og rettstrekninger. Hvert slikt opptak hjelper også med å forbedre pumpgjenkjenningen for klokka.",
