internal fun portText(key: String, lang: String): String? =
    PORT_TEXTE[lang]?.get(key) ?: PORT_BRUECKE[lang]?.let { PORT_TEXTE[it]?.get(key) } ?: PORT_TEXTE["en"]?.get(key)
